    "annotation": "Капибара Клара — самая сварливая капибара на свете. Она разбирается в древностях, любит вкусно поесть и принимать ванну с пенкой. А вот глупые вопросы, приключения и нераскрытые тайны терпеть не может. А их в джунглях хоть отбавляй! Когда в музее исчезает древняя маска Короля Ягуара, Клара берётся за дело. Вместе с рассеянным полицейским коати Матеушем она выходит на след хитроумного похитителя. Им предстоит иметь дело с танцорами сальсы, ленивцем, шаманом леопардов, коварной игуаной Джонсом и древними заклинаниями. Но это не просто детектив! Здесь тебя ждут неожиданные повороты, звериные загадки и реальные факты о животных Латинской Америки. Кто сказал, что расследования — это только для людей?",
