    "annotation": "Мурлик Фирс очень хотел найти своего кота, чтобы заботиться о нём, ведь мурлики - такие милые и добрые существа! Наконец, после долгих поисков, ему повезло - да вот только кот его оказался мрачным и неприветливым? Но со временем Фирс понял, что первое впечатление обманчиво, и их с Котом знакомство переросло в крепкую дружбу. Ведь на самом деле Кот чувствовал себя одиноким и ему очень нужен был кто-то, с кем можно вместе гулять под дождём, смотреть на море, шутить, улыбаться и просто мечтать? Яркие, забавные и трогательные иллюстрации к книге нарисовала замечательная художница Татьяна Глущенко. Для младшего школьного возраста",
