    "annotation": "На каникулах Энн отправилась с бабушкой и дедушкой в путешествие на лодке. И своего любимца, озорного щенка ирландского сеттера Фреда, взяла с собой. Но вот беда - Фред никак не мог привыкнуть к жизни на лодке и в конце концов сбежал… И как теперь Энн найти любимца? Лодка не дом, она плывет от одной стоянки до другой, и даже если щенок попытается вернуться к подруге, то не найдет ее на прежнем месте. Но любовь, преданность и хороший нюх обязательно помогут Фреду найти хозяйку! Для младшего школьного возраста",
