    "annotation": "Главная книга по мультсериалу Disney \"Гравити Фолз\", созданному Алексом Хиршем! Абсолютный бестселлер среди фанатов мистического городка! Перед вами тот самый дневник, который Диппер нашел в самом начале лета. Его страницы не раз мелькали на экранах за просмотром \"Гравити Фолз\". С помощью дневника двойняшки Диппер и Мэйбл раскрывали тайны, узнавали все больше секретов и преодолевали препятствия во время летних каникул у дяди Стэна. С этой книгой вы сможете подробно изучить всех существ \"Гравити Фолз\", которые в сериале только упоминались, описания локаций, историю приключений дяди Форда и даже схему устройства путешествия во времени! Дневник станет замечательным подарком для любого из поклонников этого мультсериала! Теги книги: Книги для детей, Гравити Фолз, Гравити Фолз книга, современная литература, эксмо книги, disney, disney книги., Диппер, Мэйбл, Хирш, Пайнс, подарок подростку, подарок фанату",
