    "year": "2019",
    "publisher": "Эксмодетство",
    "annotation": "Полистать Зои всегда знала, что щенок - это очень и очень большая ответственность. Поэтому хоть она и мечтала о щенке, но не торопилась просить его у родителей. Однажды девочка познакомилась со Скаутом, щенком бернского зенненхунда, длиннолапым, непоседливым и очень дружелюбным. Хозяева Скаута недавно переехали в город, у них новая работа, и они не могли уделять щенку столько внимания, сколько нужно, отчего он начал проказничать. Зои вызвалась помочь - гулять с малышом, играть, дрессировать. Только с каждым днём она всё больше привязывалась к мохнатому ученику. Хозяева Скаута решили, что не рассчитали свои силы и решили вернуть щенка заводчику. Значит, Зои и Скауту предстоит разлука?.. Для среднего школьного возраста. Полистать",
