    "year": "2021",
    "publisher": "Эксмо",
    "annotation": "Ратц и Мими — ленивец и бабочка, которая живёт в его шерсти. И хотя вся эта история — забавный вымысел, этот факт взят из настоящей дикой природы — в шерсти ленивцев и правда живут бабочки! Старина Ратц из этой истории больше всего любит поспать, а вот Мими — сущая егоза, она обожает убираться и веселиться. И, конечно же, она не может пропустить мимо ушей объявление о гонке на реке, за победу в которой обещают самые соблазнительные призы (вроде торта из листьев и реактивной швабры). Но когда соревнование начинается, оказывается, что это вовсе не соревнование, а… А вот во что на самом деле влипли Ратц и Мими на этот раз, вы узнаете, прочитав историю «Плавучий диван»! В ней вас ждут уморительные приключения животных в джунглях, которые сопровождаются забавными цветными иллюстрациями. А иллюстрации эти нарисовал тот же художник, что и оформлял книги-бестселлеры «Не открывать! Кусается!» и др. <br> Небольшой объём текста, яркое оформление и лёгкий сюжет сделают эту книгу идеальным подарком для начинающего читателя, который ещё только открывает для себя мир литературы. Ну а тем детям, которые уже активно читают, эта книга станет добрым и весёлым другом, с которым здорово провести интересный вечер. Вперёд к приключениям вместе с Ратцем и Мими",
