    "annotation": "Я оставила свой род, чтобы жить той жизнью, которую выбрала сама. Но прошлое не отпустило. Мой брат-близнец пропал, и теперь родители требуют заменить его на Турнире четырёх стихий, чтобы защитить честь рода. Но мне плевать, кто выиграет в этом глупом соревновании магов, мне не нужна победа и возможность обучения у полубогов. Я собираюсь найти брата. А параллельно не раскрыть обман, не выдать, что я — не он. Особенно этому наглому магу воды с ледяным взглядом. Вот только маг постоянно возникает там, где его не просят",
