    "publisher": "Клевер",
    "annotation": "Новый учебный год только начался, а бельчонок Джимми уже хвастается друзьям, что к началу зимы папа построит ему лучший в мире дом на дереве! Возможно, это и правда так, ведь папа Джимми — владелец крупнейшей в округе строительной компании. Крольчишка Венди твердо намерена бросить хвастуну вызов. Но как построить домик, если ты в жизни не держала в лапках гвоздя и у тебя нет папы, который мог бы помочь? Никто из друзей не верит, что Венди успеет в срок. Но, как оказывается, у маленькой крольчишки уже созрел отличный план... Все решится к началу зимы. А в канун Нового года друзей Венди ждет кое-что грандиозное",
