    "publisher": "Рипол-Классик",
    "annotation": "Бен Коффин - мальчик, у которого нет своей странички в фейсбуке, нет у него и друзей, есть только приемная мама. Он сирота и поэтому хорошо знает, как люди могут уходить не попрощавшись. Лучшая компания для него - это персонажи фантастических романов и \"Звездных войн\". Но однажды в его жизни появляется маленький бездомный пес, а затем и потрясающе яркая девчонка Галлея (да, да, ее зовут как знаменитую комету). Галлея носит наряды безумных цветов, ее смех способен осветить самый мрачный день, и папа у нее - настоящий волшебник! Бен мог бы сказать про себя, что абсолютно счастлив, если бы его не мучил один сложный вопрос: \"Если дружба - самое большое сокровище, то почему она не может длиться вечно?\" Для младшего школьного возраста",
