    "publisher": "Эксмодетство",
    "annotation": "Полистать Однажды Лили нашла в лесу настоящий клад — трёх крошечных котят. Девочка и вся её семья позаботились о малышах и постарались найти им новый дом. Только Лили очень привязалась к одному спасённому — белоснежному котёнку Стенли. Она мечтала оставить Стенли у себя, только в их семье уже есть питомец — пёс, который не очень-то дружит с кошками… Эта история про то, как подружить котёнка и щенка! Это потребует очень много труда, внимания и заботы! Серия-бестселлер! Дети по всему миру обожают эти книги про котят и щенят! Истории Холли Вебб бережно учат чуткости, любви, доброте и ответственности. Книга издана на белой бумаге, внутри достаточно крупный шрифт и потрясающей красоты чёрно-белые иллюстрации, которые позволят детям переключать внимание, не нагружая чрезмерно глаза. Идеальна для родителей, которые хотят, чтобы дети втянулись в чтение. Для среднего школьного возраста. Полистать",
