    "publisher": "Самокат",
    "annotation": "Парр М. Тоня Глиммердал. 10-е изд Девочка Тоня по прозвищу «гроза Глиммердала» — единственный ребенок в норвежской глухой деревушке. Тоне десять лет, у нее есть снегокат и твердая уверенность в том, что главное в жизни — «скорость и самоуважение». А еще у Тони есть лучший друг — старик Гунвальд, который печет для нее кексы и играет ей на скрипке. «Гунвальд, что бы ты делал без меня?» — часто спрашивает Тоня. «Я бы сам закопал себя в землю и сдох», — отвечает Гунвальд«. «Тоня Глиммердал», вторая книга Марии Парр, — это повесть о настоящей дружбе и о том, что иногда дети оказываются намного мудрее взрослых, помогая им примириться со своим прошлым и радоваться настоящему. Норвежская детская писательница Мария Парр — автор трех книг, трех абсолютных мировых бестселлеров: «Вафельное сердце», «Тоня Глиммердал» и «Вратарь и море» (продолжение «Вафельного сердца»), — все они переведены более чем на 20 языков и продаются многотысячными тиражами",
