    "year": "2023",
    "publisher": "Рипол-Классик",
    "annotation": "Иванов А.В. Пищеблок // \"Жаркое лето 1980 года. Столицу сотрясает Олимпиада, а в небольшом пионерском лагере на берегу Волги всё тихо и спокойно. Пионеры маршируют на линейках, играют в футбол и по ночам рассказывают страшные истории; молодые вожатые влюбляются друг в друга; речной трамвайчик привозит бидоны с молоком, и у пищеблока вертятся деревенские собаки. Но жизнь пионерлагеря, на первый взгляд безмятежная, имеет свою тайную и тёмную сторону. Среди пионеров прячутся вампиры. Их воля и определяет то, что происходит у всех на виду. \"Пищеблок\" - простая и весёлая история о сложных и серьёзных вещах. Есть дети как дети - с играми, ссорами, фантазиями и бестолковостью. Есть пионерство, уже никому не нужное и формальное. А есть вампиры, которым надо жить среди людей, но по своим вампирским правилам. Как вампирская мистика внедряется в мёртвые советские ритуалы и переделывает живое и естественное детское поведение? Как любовь и дружба противостоят выморочным законам идеологии и вампиризма? Словом, чей горн трубит для горниста и под чей барабан шагает барабанщик?\" Алексей Иванов",
