    "publisher": "Издательство АСТ",
    "annotation": "Эдуард Успенский: Маленькие сказки про Чебурашку. Эдуард Успенский написал специально для малышей маленькие сказочки про жизнь крокодила Гены и его самого лучшего друга Чебурашки. Эти неразлучные друзья очень интересно проводят время: празднуют новоселье, строят скворечник для бабочки, катаются на лыжах, собирают грибы и вместе противостоят зловредной Шапокляк. Читайте вместе с детишками эти сказочные истории, а когда малыши подрастут, они сами начнут читать эту книжку про своих уже любимых героев! \"Библиотека для дошколят\" – это новая серия для самых маленьких читателей и слушателей!",
