    "annotation": "Ледниковые люди очень чистоплотны. Они моются два раза в год: в начале и в конце долгой зимы. Ледниковые люди очень красивы. Они массивные, как быки, горбатые, как бизоны, и мохнатые, как медведи. Ледниковые дети ходят в школу. Охота, рыбалка и собирательство - основные уроки. Но есть и другие: обработка кремня, постройка хижины, магический рисунок... Вместо контрольной проводят Испытание Мальчика-с-пальчик. А вместо оценок выдают Годовые Копья разного размера. О буднях и праздниках, приключениях и развлечениях ледниковых детей расскажет Неандертальский мальчик. Его историю оживил самый весёлый детский художник - дядя Коля Воронцов. Добро пожаловать в ледниковый период! Для детей младшего школьного возраста",
