    "year": "2024",
    "publisher": "",
    "annotation": "Издание подарочного формата в твёрдом переплёте с выпуклыми элементами и частичным лаком. Цветные форзацы. Плотная белая бумага. Чёткий крупный шрифт. Яркие полноцветные иллюстрации. Летние каникулы — лучшее время для путешествий! Поэтому Карандаш и Самоделкин вместе с учениками отправляются в увлекательный полёт на воздушном шаре. Они направляются в Африку. А их новый друг профессор Пыхтелкин расскажет, почему этот жаркий континент называют Страной шоколадных деревьев. Увлекательные и добрые сказочные повести известного детского писателя Юрия Дружкова \"Приключения Карандаша и Самоделкина\" и \"Волшебная школа Карандаша и Самоделкина\" обрели невероятную популярность сразу после первого выхода из печати. Даже знаменитый классик Корней Иванович Чуковский сетовал, что смог получить в библиотеке первую книгу только спустя три месяца ожидания: такая была очередь на чтение! Это неудивительно: ведь главных героев — волшебного художника Карандаша и железного мастера Самоделкина — знала вся страна. Они были главными персонажами самого популярного детского журнала \"Весёлые картинки\", тиражи которого доходили до 9,5 миллионов экземпляров в месяц! Спустя годы сын Юрия Дружкова, писатель Валентин Постников, придумал продолжение любимых с детства историй. Любознательные, смелые и неунывающие человечки отправляются в невероятные, захватывающие путешествия, не боясь трудностей и опасностей. А юные читатели, как и прежде, затаив дыхание, следят за их приключениями",
