    "annotation": "Возвращение во вселенную саги \"Голодные игры\". История становления будущего президента Сноу. Читайте книгу и смотрите фильм — в ноябре 2023 года в кино выходит голливудская экранизация! 64 года назад Кориолан Сноу был восемнадцатилетним юношей, мечтающим о славе и уважении. Единственная возможность достичь желаемого — стать наставником трибута-победителя на очередных Голодных играх. Но пока что Сноу катастрофически не везет — ему предстоит работать с девушкой из самого бедного дистрикта — Двенадцатого. С этой книгой ищут: Коллинз, Сьюзен Коллинз, Голодные игры, Баллада о змеях и певчих птицах, фантастика, антиутопия, боевая фантастика, Кориолан Сноу, Люси Грей Бэйрд, экранизированные книги",
