    "publisher": "Эксмодетство",
    "annotation": "Полистать Элфи, белоснежный щенок вест хайленд уайт терьера, быстро подружился со своей новой семьей. Девочка Эви, его маленькая хозяйка, уделяла ему всё свободное время — вместе они бегали в парке, читали книги, валялись на диване и смотрели телевизор. Но жизнь щенка изменилась с рождением младшего брата Эви. Вдруг все — и папа, и мама, и даже любимая хозяйка, перестали обращать на Элфи внимание, забывали с ним погулять или поиграть, а когда он напоминал о себе, то почему-то ругали. Казалось, он всё делает невпопад. Может быть, он им просто надоел? Как же Элфи снова завоевать любовь и доверие всей семьи? И захочет ли Эви снова заботиться о нем, как прежде? Холли Вебб — писательница, популярная во всём мире, но особенно её полюбили в России, где её книги продаются миллионными тиражами. Её истории бережно учат чуткости, любви и доброте. Книга издана на белой бумаге, внутри достаточно крупный шрифт красивые чёрно-белые иллюстрации, которые позволят детям переключать внимание, не нагружая глаза. Для младшего школьного возраста. Свернуть Полистать",
