    "annotation": "НЕЗАКОННОЕ ПОТРЕБЛЕНИЕ НАРКОТИЧЕСКИХ СРЕДСТВ, ПСИХОТРОПНЫХ ВЕЩЕСТВ, ИХ АНАЛОГОВ ПРИЧИНЯЕТ ВРЕД ЗДОРОВЬЮ, ИХ НЕЗАКОННЫЙ ОБОРОТ ЗАПРЕЩЕН И ВЛЕЧЕТ УСТАНОВЛЕННУЮ ЗАКОНОДАТЕЛЬСТВОМ ОТВЕТСТВЕННОСТЬ. Об авторе: Генри Марш — всемирно известный британский ПРАКТИКУЮЩИЙ нейрохирург, оперирует пациентов с наиболее тяжелыми случаями. Профессор, научный руководитель и основатель Международного центра нейрохирургии на Украине (Киев), совместно с Игорем Курельцом. Особенности книги: Переведена на 17 языков! Вошла в список бестселлеров New York Times, становилась лауреатом или попадала в шортлист нескольких премий! В 2007 году вышел документальный фильм \"Английский хирург\", в котором мы можем наблюдать за работой Генри Марша во время проведения настоящей операции. О чем эта книга: Книга — о буднях нейрохирурга, его работе, его выборе, за кого из пациентов бороться, а кого отпустить. Конечно, не хотелось бы попасть к нему на прием, но иногда это случается. И хочется, чтобы врач делал свою работу хорошо. Но все мы забываем, что нейрохирурги тоже люди, со своими заботами, обидами, недосыпом. головной болью, наконец. Каково это — быть ответственным за жизнь и здоровье человека? Где черпают силы люди, от которых зависит так много? Продолжающаяся серия \"Медицина без границ\". Книги о тех, кто спасает жизни, — книги о работе медперсонала",
