    "year": "2025",
    "publisher": "Клевер",
    "annotation": "«Сквозь всё живое, словно река, течет особая магия. Ее сила согревает землю, заставляет семена прорастать, а цветы — распускаться». Старая колдунья Ула надеется положить конец затянувшейся зиме с помощью магического зелья. Вот только волшебство идет не по плану, и вместе с приходом весны в ее жизни появляется малышка Винка, которая совсем не похожа на других детей и обладает удивительными суперспособностями... Трогательный и мудрый комикс о привязанности и магии времени, который заставляет по-новому взглянуть на мир и пробуждает веру в чудо. Комикс «Магия весны. Ула и Винка» — добрый и глубокий рассказ, он напоминает о магии повседневности, которую обычно не замечаешь. Продуманный сюжет, динамичные иллюстрации и небольшой объем текста — книжка читается на одном дыхании и обязательно понравится даже тем ребятам, которые пока не любят большие произведения.",
