    "year": "2022",
    "publisher": "Эксмо",
    "annotation": "Ратц — ленивец, а Мими — бабочка, которая живёт в его шерсти (да-да, такое и правда бывает в природе!). Старина Ратц из этой истории больше всего любит поспать, а вот Мими — сущая егоза, она обожает убираться и веселиться. Но однажды Мими похитили! И Ратц (который очень не любит шевелиться, но что поделать) отправляется её спасать! Вот только он и представить себе не мог, что ему предстоит встреча с загадочным. А вот с кем столкнутся Ратц, Мими и их друзья на этот раз, вы узнаете, прочитав историю \"Похититель бабочек\"! В ней вас ждут уморительные приключения животных в джунглях, которые сопровождаются забавными цветными иллюстрациями, которые нарисовал тот же художник, что и оформлял книги-бестселлеры \"Не открывать! Кусается!\" и др. Небольшой объём текста, яркое оформление и лёгкий сюжет сделают эту книгу идеальным подарком для начинающего читателя, который ещё только открывает для себя мир литературы. Вперёд к приключениям вместе с Ратцем и Мими!",
    "locationNote": "Местоположение: Сагунто. Доступность метро на станциях Colón и Aragón в определённые дни и часы.",
    "sourceUrl": "https://www.wildberries.ru/catalog/66077697/detail.aspx",
