    "isbn": "",
    "year": "2021",
    "publisher": "РОСМЭН",
    "annotation": "«Котобой» – цикл увлекательных великолепно иллюстрированных книг для детей 4-8 лет про приключения отважных и любознательных котов. Придумал эти истории популярный детский писатель Андрей Усачёв – признанный классик современной детской литературы, чьи произведения покорили миллионы детей и взрослых! Где-то на севере есть удивительная деревушка Котьма, и живут в ней одни только коты – самостоятельные и веселые. Однажды из старой лодки они сделали настоящую парусную яхту и отправились в плавание, да не за какой-нибудь мелкой рыбёшкой, а за целым китом! Яркие смешные иллюстрации к приключениям котов-мореходов нарисовал известный художник дядя Коля Воронцов, создавший Кота Помпона. Дети c удовольствием будут рассматривать рисунки, находя в них множество забавных деталей. Эта книга станет замечательным подарком для мальчиков и девочек и поможет привить любовь к художественной литературе и чтению. Книга подойдет для семейного чтения с ребенком, а также в качестве самостоятельного чтения детьми",
    "locationNote": "Местоположение: Сагунто. Доступность метро на станциях Colón и Aragón в определённые дни и часы.",
