    "year": "2022",
    "publisher": "Эксмодетство",
    "annotation": "Полистать Папа Мейзи - моряк, все время в плаваниях, и девочка очень давно его не видела. Папа не забывает свою дочку, вот и сейчас прислал подарок, ожерелье с подвеской. Подвеска покрыта загадочными египетскими иероглифами, и Мейзи, как начинающему детективу, не терпится расшифровать надпись. Разумеется, тут требуется помощь знатока. Но у крупнейшего ученого по Древнему Египту своя беда - пропал золотой скарабей, гордость его коллекции. \"Так это целых два египетских ребуса!\" - обрадовалась девочка и с жаром принялась за эти загадки. Образцовый детектив для детей - тайны, которые расследует Мейзи Хитчинс, под силу разгадать ребёнку! Неутихающая популярность этой серии свидетельствует, что секреты Лондона XIX века волнуют... и наших детей! Здесь полно приключений, трогательных и смешных моментов и удивительных фактов из истории викторианского Лондона! Для среднего школьного возраста. Полистать",
