    "annotation": "Полистать Сколько себя помнила Скарлетт, столько упрашивала родителей взять котенка. И, наконец, у девочки появился питомец - рыжий с белым котенок, которого назвали Пиратом. Озорной, игривый и ловкий котенок сразу же подружился со своей маленькой хозяйкой и вместе они поставили на уши весь дом. Но Скарлетт нужно ходить в школу, а Пират в это время скучает дома. И вот однажды, когда девочка была в школе, котенок пропал. Как он выбрался из запертого дома? И куда ушел? Сумеет ли Скарлетт найти своего любимца? Для младшего школьного возраста. Полистать",
