    "id": "b-33d67281b1ca",
    "requestId": "167",
    "title": "Mother cat's tales",
    "author": "Несбит Э.",
    "section": "exchange",
    "catalogStatus": "Частная библиотека",
    "libraryKey": "user:eac4b24812ce",
    "sourceKind": "user",
    "availability": "available",
    "audience": "children",
    "cover": "https://basket-12.wbbasket.ru/vol1779/part177997/177997292/images/big/1.webp",
    "isbn": "978-5-8112-7082-8",
    "year": "2022",
    "publisher": "Айрис-пресс",
    "annotation": "Несбит Э. Рассказы мамы-кошки - Mother Cat's Tales В основу адаптации положены известные новеллы \"Истории про кошек\" знаменитой английской детской писательницы Эдит Несбит (1858-1924). Увлекательность рассказов, приправленных добрым юмором, а также выразительный и доступный для понимания английский язык делают их неотразимо привлекательными не только для детей, но и для взрослых. Все семь рассказов объединены одним началом - их рассказывает своим котятам мама-кошка. Каждый день, ближе к вечеру, большая полосатая пушистая кошка и её три разномастных котёнка нежатся на сене в амбаре. Каждый раз один из котят просит мать рассказать какую-нибудь интересную историю, и она после недолгих уговоров соглашается. Данное пособие разработано в соответствии с требованиями Федерального государственного образовательного стандарта (ФГОС). Оно поможет учащимся начальной школы подготовиться к обязательному для каждого ученика итоговому экзамену по английскому языку в новом формате. После каждого рассказа следуют комментарий и перевод трудных слов и выражений, а также упражнения, которые учитывают новые требования итоговой аттестации. Они направлены не только на проверку понимания текста, но и на отработку лексики, грамматики, а также развитие умений чтения, устной речи, письма. Упражнения имеют два уровня сложности; что даёт возможность каждому ученику продемонстрировать свой уровень знаний и умений. В конце книги даны словарь, тест в формате итогового экзамена за 4-й класс, а также ответы ко всем упражнениям и тестовым заданиям. Пособие адресовано учащимся начальных классов образовательных учреждений, начиная со второго года обучения, а также широкому кругу лиц, изучающих английский язык",
    "locationNote": "Местоположение: Сагунто. Доступность метро на станциях Colón и Aragón в определённые дни и часы.",
    "sourceUrl": "https://www.wildberries.ru/catalog/177997292/detail.aspx",
