    "publisher": "Феникс-премьер",
    "annotation": "Две сестры, Арина и Даша, постоянно ссорятся. Родители пытаются помирить их, сделать так, чтобы девочки подружились. В этой истории происходит настоящее новогоднее чудо - девочки находят маленького котёнка на улице, и желание помочь ему и подарить настоящую семью - сближает сестёр. Получится ли у сестёр забрать малыша домой, если родители против, котёнок куда-то пропал, а куранты вот-вот пробьют двенадцать! Для детей 4-6 лет",
