    "annotation": "Приключения Кота и мурлика Фирса продолжаются. Однажды на пороге домика у маяка появилась незнакомка в бирюзовой шубке. Друзья приветливо встретили её, но странное существо было уж слишком угрюмым.Несмотря на радушный приём, Зюря, а это была именно она, никак не хотела дружить с хозяевами домика. Вечно со всеми ссорилась, уходила гулять сама по себе, однажды даже уплыла на необитаемый остров, а ещё то и дело меняла цвет шубки. Но Кот и мурлик помогли Зюре понять очень важную вещь. Друг не обязан во всём с тобой соглашаться, но он всегда будет рядом,несмотря ни на что",
