    "year": "2026",
    "publisher": "Азбука",
    "annotation": "Великий Гёте задумал своего «Фауста», когда ему было немногим больше двадцати лет, а завершил трагедию за несколько месяцев до кончины. Это произведение стало итогом философских и художественных исканий автора — поэта, драматурга, прозаика, крупнейшего ученого своего времени, человека энциклопедических познаний. Герой трагедии доктор Иоганн Фауст жил в первой половине XVI века и слыл магом и чернокнижником, который, отвергнув современную науку и религию, продал душу дьяволу. О Фаусте ходили устные легенды, он был героем театральных представлений, к его образу обращались авторы — Г. Р. Видман, К. Марло, Ф. М. Клингер, Г. Э. Лессинг и другие. Под пером Гёте история о Фаусте, посвященная вечным темам познания жизни и трудности человеческого пути, стала одной из вершин мировой литературы. Серия книг «Мировая классика» — полные тексты произведений русской и зарубежной литературы, которые подходят для школьной программы и внеклассного чтения. Классическое оформление в твёрдом переплёте, удобный формат и доступная цена делают серию практичным выбором для школьника и домашней библиотеки",
