    "annotation": "В Котофеевке настоящее событие — приезжает цирк! Невероятное представление, мировые звёзды, шоу, которое перевернёт с нижних лап на верхние всех жителей! И как вы думаете, кто в центре событий? Конечно, Федя, Вася и Тося! Ни много ни мало, они решаются на побег с цирком! Что может быть прекраснее, чем судьба настоящего артиста? Приключения начинаются! 5 причин купить книгу: • Новая книга о весёлых котах Рины Зенюк: на этот раз в Котофеевку приезжает Цирк! • Федю, Васю и Тосю ждёт настоящее приключение и впервые за пределами Котофеевки! • Поучительная история со счастливым концом о семейных ценностях и настоящей дружбе • Большое количество иллюстраций, увеличенный формат, плотная бумага, крупный шрифт • Подходит как для чтения родителями детям, так и для самостоятельного чтения ребенка Все КНИГИ СЕРИИ «У нас в Котофеевке» (поиск на Wildberries по артикулу): 296028788 - Сборник 1(В сборник вошли пять книг) 608825716 - Сборник 2 (В сборник вошли пять книг) 277580454 - Снежный гость. 217013299 - Сюрприз для мамы. 150462184 - Как Федя Вася и Тося на рыбалку ходили. 171231370 - Большие гонки. 188137047 - Цирк и не только. 135791072 - Ловушка для Кота Мороза. 199632745 - На что ловятся котофеечки. 259765419 - Гуси-Лебеди. 404243525 - Ай да концерт! 208448088 - Кошки-мышки. 233243709 - Книга с наклейками. Круглый год в Котофеевке. 259767560 - Времена года. Раскраска по номерам. 259766772 - Про Федю Васю и Тосю. Раскраска по номерам",
