    "annotation": "Книга Петронелла и злой пекарь, автор Сабина Штэдинг. Рекомендуемый возраст: от 11 до 14 лет. Четвертая книга в серии о доброй и весёлой маленькой колдунье Петронелле, в которой Петронелла и ее друзья помешают злому пекарю захватить мельницу.Стоит жаркий август, а у Петронеллы, необычной доброй и весёлой ведьмы, забот невпроворот! Плюгавиц, злой пекарь и бывший начальник папы близнецов, решил купить мельницу! А планы у пекаря злодейские: семья Лины и Луиса уедет, он вырубит сад и заасфальтирует под парковку, из пруда сделает аквапарк, старый дом снесет. Надо ему срочно помешать! Для детей среднего школьного возраста. Теги: сказка; для детей; приключения; волшебная история; петронелла; истории про петронеллу; петронелла книги; ведьма петронелла; сказки для детей; ситрии для детей; проза для детей",
