    "annotation": "Новогодняя книга про маленького робота Ро, прилетевшего на Землю в поисках энергии. Новогодние сказки, которые пишет и иллюстрирует Ольга Фадеева, заряжены волшебством и добротой. Зима - время, когда энергии не хватает всем нам. Новый год - исключение. В эти дни на всей Земле случаются настоящие чудеса и сбываются мечты. Но что, если чудо требуется пришельцу? Брат и сестра, Стёпка и Ася, постараются ему помочь. Зимние книги для детей помогают дождаться наступления Нового года и уютно провести время на новогодних каникулах. Сказки для детей - как волшебное лекарство от плохого настроения. Эти новогодние истории - не исключение. Готовите новогодние подарки для детей? Не забудьте: среди игрушек и развивающих игр должны быть и детские книги. Например - книги, которые написала Ольга Фадеева. Издательство речь выпускает множество чудесных вещей. И это не только новогодние рассказы. У нас найдётся книга на любой сезон. Заходите в наш профиль и добавляйте издательство Речь в любимые бренды. Здесь каждый найдёт подарок на Новый год и Рождество себе по вкусу",
