    "publisher": "Эксмо",
    "annotation": "И все-таки этот семейный ужин Уинстон представлял себе по-другому. Противные племянники профессора Вернера, то и дело готовые схватить его за хвост, - что может быть хуже?! Но оказалось, что издевательства маленьких мучителей не самое страшное на свете. Ведь после ужина Уинстон чуть не умер от боли в животе. Ужасный скандал: ветеринар уверен, что усатого детектива хотели отравить! Читателя ждет невероятно важное детективное расследование! Ведь кто-то пытался отравить самого Уинстона Черчилля, короткошерстного британца и крутого детектива!Серия-бестселлер! Награждена Премией котов-детективов и входит в список ТОП-3 лучших детских книг по версии авторитетного немецкого портала \"Lovely Books\". Книги о коте Уинстоне помогли уже сотне тысяч детей полюбить чтение. Они не только развлекают, но и учат ответственности, внимательности по отношению к близким и друзьям и отзывчивости. Теги книги: книги для детей, книги для подростков, детские детективы, детективы для детей, загадки для детей, мейзи хитчинс",
