    "year": "2022",
    "publisher": "",
    "annotation": "Основы робототехники, начала астрономии, космическая фантастика - это всё понятно. Но зачем в Школе юных фантастов русский язык? Синонимы, антонимы и прочая лексика - ещё куда ни шло, но орфография? Данил вместе с новыми друзьями Игорем и Сашкой обязательно это выяснит, а ещё найдёт Блок Экспериментальных Сведений, сбежавший от инопланетян. И, конечно, легко и быстро выучит правила и узнает много нового из истории правописания. Веселые приключения от Светланы Лавровой, автора книги \"Замок графа Орфографа\", дополнены основными правилами орфографии и заданиями для отработки полученных знаний. Для среднего школьного возраста",
