    "annotation": "Книга \"Королевство кривых зеркал\" Добрая, умная и необычайно увлекательная сказочная повесть Виталия Губарева «Королевство кривых зеркал» – одна из самых любимых детских книг в нашей стране, давно ставшая классикой. В ней пятиклассница Оля волшебным образом попадает в зазеркалье, где всё наоборот. Чтобы вернуться домой, ей придется пройти множество испытаний. И это не просто испытания – это проверка на характер и умение дружить. Прочитав эту книгу, каждый поймет: чтобы узнать, кто ты есть на самом деле, стоит посмотреть на себя со стороны",
