    "year": "2024",
    "publisher": "Издательство Речь",
    "annotation": "Муся, Плюшка и Элиза - великие детективы. Но хозяева считают, что они всего лишь милые домашние питомцы.Перед вами детский дачный детектив, в котором кошки, коты и собаки детективы разоблачают похитителей молока, лисичек и золотой цепочки. А ещё им удаётся снять несправедливые обвинения с тех, кто выглядит подозрительно, но на деле ни в чём не виноват.В книге двенадцать рассказов, в каждом - новая детективная история. В каком порядке читать детские книги про \"Кошачье детективное агентство\": Кошачье детективное агентство, арт. 11100301 У кошек всегда каникулы, арт. 14069397 Кошки идут по снегу, арт. 16405746 Весна - время кошек, арт. 21249407 Учитесь у кошек, арт. 68921359 Книги серии дети читают сами и ждут продолжения. Это прекрасный образец современной детской прозы, добрая книга о приключениях и дружбе.Детский детектив сопровождают весёлые и атмосферные иллюстрации Ольги Громовой. Книга для школьников 1, 2, 3, 4, 5 класса и их родителей",
