    "annotation": "Полистать Эмма любит лошадей и с удовольствием занимается верховой ездой. К тому же на конюшне живут несколько кошек, грациозных, диких и необщительных. Девочка старалась с ними подружиться, но никак не получалось. Когда одна из них родила котят, хозяйка конюшни решила раздать малышей в добрые руки. Значит, кто-то должен приучить их к человеку. И начинать нужно как можно скорее, пока котята еще совсем крохотные и слепые. Эмма обрадовалась и вызвалась стать кошачьей няней. Вот только девочка не учла, что очень сильно привяжется к одному из малышей и не сможет с ним расстаться. Теперь Эмме предстоит уговорить родителей завести дома не просто котёнка, а дикого котёнка, мало привыкшего к людям. Эта история про приручение. И про то, каким насколько надо быть ответственной и заботливой девочкой, чтобы подружиться с диким котёнком! Серия-бестселлер! Дети по всему миру обожают эти книги про котят и щенят! Книга издана на белой бумаге, внутри достаточно крупный шрифт и красивые чёрно-белые иллюстрации. Для среднего школьного возраста. Свернуть Полистать",
