    "annotation": "Книга Петронелла и волшебная книга, автор Сабина Штэдинг. Рекомендуемый возраст: от 11 до 14 лет. Пятая книга в серии о доброй и веселой маленькой колдунье Петронелле.Наступила дождливая осень, и все жители яблоневого сада начали подготовку к зиме. Однако внезапно куда-то пропали яблочные человечки! Может быть, их похитил злой кикимор? Пёс по кличке Грызлик нападает на его след, ведущий в лес за садом Петронеллы... Но вот незадача - сёстры Петронеллы не вернули ей волшебную книгу! Как же ей теперь победить кикимора и спасти яблочных человечков? Сабина Штэдинг - \"новая немецкая Астрид Линдгрен\", автор главного европейского сказочного бестселлера 2016 года!Для детей среднего школьного возраста. Теги: сказка; для детей; приключения; волшебная история; Петронелла; петронела",
