    "id": "b-5276e6d35bd7",
    "requestId": "134",
    "title": "Все сказки о кролике Питере",
    "author": "Беатрис Поттер",
    "section": "exchange",
    "catalogStatus": "Частная библиотека",
    "libraryKey": "user:eac4b24812ce",
    "sourceKind": "user",
    "availability": "available",
    "audience": "children",
    "cover": "https://basket-16.wbbasket.ru/vol2557/part255769/255769282/images/big/1.webp",
    "isbn": "",
    "year": "2024",
    "publisher": "",
    "annotation": "Ознакомиться со всей книгой в электронном виде можно по ссылке на сайте издательства СЗКЭО РФ Подарочное иллюстрированное издание отпечатано на матовой мелованной бумаге Омела с закладкой ляссе одного цвета с капталом. БМЛ Том 280 Беатрис Поттер Все сказки о кролике Питере Хелен Беатрис Поттер (1866–1943) — английская детская писательница и художница. В 1902 году ее «Сказка о кролике Питере» впервые вышла в печать. С тех пор Беатрис начала регулярно издавать свои новые детские книжки. Сказки Беатрис Поттер в наши дни переводятся на множество языков и издаются многочисленными тиражами. Данное издание включает двадцать три сказочные истории про кролика Питера и многих других персонажей, придуманных Поттер. Текст дан в переводе Сергея Юрьевича Афонькина. Хелен Беатрис Поттер (1866–1943) — английская детская писательница и художница. Беатрис родилась в состоятельной лондонской семье. С малых лет она проявляла способности к рисованию, которые ее отец, сам увлекавшийся рисованием и фотографированием, охотно поддерживал. Он водил дочь в Музей естествознания, где она могла часами практиковаться в рисовании животных с натуры. Каждое лето семья проводила в загородном доме, где дети могли любоваться природой. Там Беатрис заполнила многочисленными зарисовками растений, зверят и птиц несколько альбомов. Вместе с младшим братом девочка собирала камни и составляла гербарий, наблюдала за повадками животных и изучала их анатомию. У детей было множество питомцев: лягушки, ящерицы и, конечно, кролики. Девочка воспитывалась несколькими гувернантками; разница в возрасте с последней из них, Энни Картер Мур, составляла всего три года. Девушки проводили много времени вместе и стали подругами. Они продолжали общаться и после замужества Энни. Предпосылки сказок о кролике Питере зародились в письмах Беатрис к Энни: Беатрис сочиняла небольшие истории про кролика и его друзей для сына Энни и сама выполняла к ним милые рисунки. Свое имя кролик в ее сказках получил от настоящего кролика Питера, который был у Беатрис в детстве, — он также был частым героем ее иллюстраций. Энни не раз говорила, что из этих маленьких сказок можно было бы составить книгу, и в 1902 году «Сказка о кролике Питере» впервые вышла в печать. До этого издатели неоднократно отказывали Беатрис в публикации, однако уже к концу года было продано двадцать восемь тысяч экземпляров ее книги. С тех пор Беатрис начала регулярно издавать свои новые сказочные истории для детей. Несмотря на свою приверженность к литературе для малышей и любовь к детям, своими детьми Беатрис так и не обзавелась, однако она стала любящей тетей для детей своего брата и заботливой крестной для дочери Энни. Беатрис искренне восхищалась сельскими красотами; свои земли и недвижимость она завещала Национальному фонду, охраняющему исторические объекты и природные ландшафты Великобритании. Культурное наследие писательницы было оценено по достоинству: в наши дни сказки Беатрис Поттер регулярно переиздаются и пользуются любовью читателей, по мотивам этих сказок неоднократно делали экранизации, а коллекция писем и рисунков Беатрис бережно хранится в музеях и библиотеках Великобритании и США",
