    "year": "2022",
    "publisher": "Детская литература",
    "annotation": "НЕСРАВНЕННАЯ ЯБЕДА-КОРЯБЕДА Одним обыкновенным осенним утром город Укромный изменился до неузнаваемости. В нём появились шоколадные тротуары, съедобный Кондитерский музей, зоопарк с доисторическими и сказочными зверями и много других удивительных вещей. И всё это подарила городу злая волшебница Я. К. Орябеда. Какая же очередная каверза коварной Ябеды-Корябеды скрывается за этими чудесами? Кто поможет разоблачить её хитроумный план? Кто найдёт в себе мужество изгнать злую волшебницу из города? Ответы на эти и многие другие вопросы вы найдёте в этой детективно-загадочной истории. СПОРТИВНАЯ КОТЛЕТА ЯБЕДЫ-КОРЯБЕДЫ Всеобщая тревога! Как сообщает проверенный источник, известная злая волшебница и хулиганка Ябеда-Корябеда опять вернулась к своим тёмным делишкам. На этот раз она задумала ни больше ни меньше как сорвать крупнейшее международное мероприятие — первые в истории Детские зимние спортивные игры! Юных спортсменов и болельщиков, а также читателей этой книги ждут нелёгкие испытания и масса неожиданностей, подстроенных командой Ябеды-Корябеды. Удастся ли преодолеть их, чтобы Игры состоялись? Кто победит — злая волшебница или любовь к спорту? И главное — при чём здесь котлета?.. Неутомимый писатель и художник Александр Семёнов, автор популярных книг о проделках Ябеды-Корябеды, представляет очередную историю с участием любимых героев. Читатель не только окунётся в круговорот весёлых и непредсказуемых событий, но и станет их непосредственным участником, узнает много интересного о зимних видах спорта. Нас находят по запросам: Бестселлеры книги популярные Детская и юношеская книга Детская книгаДетская литература рассказы Детские книги сказки Детские рассказы Детские сказки Добрые сказки Издательство Детская литература Интересные книги для подростка Книга для подростков Книги 12+ Книги детские книги Книги для девочек подростков Книги для детей книга Книги для мальчиков подростков Книги для подростков в 12 лет Книги для подростков фэнтези Книги подростковые Подарок подростку книги Ябеда Корябеда Подарок ребенку Подростковая литература Подростковые книги Сказка Сказки для детей книги Сказки и рассказы для детей Фантастика и фэнтези Художественная литература для детей Художественная литература для подростков",
