    "annotation": "Петронелла - не обычная ведьма, а добрая и веселая. И живет она не в какой-нибудь избушке в темном лесу, а в волшебном домике на яблоне, в центре фруктового сада, что неподалеку от мельницы. Та мельница много лет стояла без хозяина, пока в один прекрасный день в нее не вселилась целая семья, да какая шумная!.Поначалу Петронелла ждала от новых соседей всевозможных бед, но как-то раз двое из новоселов явились к ней в гости и оказались симпатичными детишками! Это были мальчик Луис и его сестренка Лина. С первой встречи Петронелла и ребята понравились друг другу, а потом и подружились. Как раз вовремя, потому что без помощи доброй ведьмы Луису и Лине нечего было бы и мечтать выиграть важный конкурс, но это уже долгая история",
