    "annotation": "Печатная книга «The Adventures of Tom Sawyer. 100th Anniversary Collection» в мягкой обложке, язык - английский. В книге 270 страниц, она напечатана на белой офсетной бумаге плотностью 80 г/м². Формат издания — 152x229 мм. Все книги аккуратно упаковываем в прочный трёхслойный непрозрачный картонный конверт. Mark Twain created the memorable characters Tom Sawyer and Huckleberry Finn drawing from the experiences of boys he grew up with in Missouri. Set by the Mississippi River in the 1840's, it follows these boys as they get into predicament after predicament. Tom's classic whitewashing of the fence has become part of American legend, and the book paints a nostalgic picture of life in the middle of the nineteenth century. Tom runs away from home to an island in the river, chases Injun Joe and his treasure, and even gets trapped in a cave for days with Becky Thatcher. The book is one of Twain's most beloved stories",
