    "isbn": "9785699775958",
    "year": "2022",
    "publisher": "Эксмодетство",
    "annotation": "Полистать Котёнок Снежинка не знала, что она котёнок и как её зовут. Она родилась в этом заброшенном холодном доме. Сначала рядом была мама, которая кормила и согревала, но потом мама исчезла, и Снежинка осталась совершенно одна. Она очень замёрзла, сильно проголодалась и так устала, что уже не могла плакать и звать на помощь и только пыталась забыться в тревожном сне. Но вдруг в дом кто-то пришёл — другая кошка, поменьше мамы, но тоже тёплая и ласковая. Эта кошка вылизала Снежинку, нашла еду, а потом снова исчезла. И вернулась уже вместе с девочкой. Неужели Снежинка обретёт дом и имя? Серия-бестселлер! Дети по всему миру обожают эти книги про котят и щенят! Истории Холли Вебб бережно учат чуткости, любви и ответственности. Книга издана на белой бумаге, внутри достаточно крупный шрифт и изумительные чёрно-белые иллюстрации, которые позволят детям переключать внимание, не перенапрягая глаза. Идеально для родителей, которые хотят, чтобы дети втянулись в чтение. Полистать",
