    "publisher": "",
    "annotation": "Девятихвостая лисица-кумихо хочет стать человеком. Для этого ей нужно прожить сто дней среди людей, не выдав себя. Однако в квартиру этажом ниже въезжает семья с маленьким ребёнком. Его плач и несчастная судьба заставляют кумихо задуматься о своём желании. История сопровождается иллюстрациями Херан.",
