    "annotation": "Полистать В этом году Дарси приняли в школьную футбольную команду, поэтому свободного времени стало совсем мало, только уроки успеть сделать. Её котёнок Чарли ещё маленький и совершенно не может понять, почему любимая хозяйка вдруг стала уделять ему так мало внимания. И будто бы обидевшись на это Чарли однажды… пропал. За пределами участка котёнку грозит много опасностей - и дикие животные, и многополосные шоссе. Дарси бросилась по соседям - но никто не встречал полосатого котёнка с белыми лапками. Правда, может быть, всё не так плохо, и хвостатого бродяжку приютила какая-нибудь добрая фея? Полистать",
