    "annotation": "Книга \"Милый дом Чи. Книга 3\" Освоившись в доме, малышка Чи отправилась покорять улицу, где встретила огромного кота по кличке Черныш. Того самого, что давеча наведывался к ним в гости. Во время своей вылазки друзья попались на глаза строгой консьержке и едва лапы от неё унесли – вот это была погоня! Увы, рассерженная дама не оставила Черныша в покое. Она решила во что бы то ни стало выселить его хозяев из дома. Папа и мама нашей Чи тоже страху натерпелись. Как же им и теперь прятать питомца, если он так и норовит выбраться во двор на поиски приключений? взаимопомощь, для детей, дорога домой, дружба, комиксы, кошки, любопытство, манга, непоседа, приключения, семья",
