    "year": "2023",
    "publisher": "Эксмо",
    "annotation": "БУДУЩИЙ ХИТ NETFLIX! Международный бестселлер от создателя культового киносериала \"Убийство\". Права на издание проданы в 30 стран. Лучшая книга года по версии New York Times, Kirkus, Library Journal. Роман вошел в список лучших книг года по версии BBC, Guardian и Evening Standard. Очень хитроумный и атмосферный детектив-триллер в лучших традициях Ю Несбё. Недаром Сорену Свейструпу предложили стать сценаристом фильма по культовому триллеру Ю Несбё \"Снеговик\". После созданного им сериала \"Убийство\" он получил репутацию подлинного мастера острого сюжета. А его дебютный роман показал всему миру: в Скандинавии появилась новая звезда триллера. Свейструп получил за эту книгу престижную остросюжетную премию Barry Award. Копенгаген. Найдено тело жестоко убитой девушки. Над ним висит каштановый человечек — куколка, сделанная из каштанов и спичек, с прорезанными глазками и улыбающимся ротиком. На фигурке обнаружены отпечатки пальцев пропавшей год назад и числящейся мертвой девочки. Но человек, признавшийся в ее убийстве, уже сидит в тюрьме. А вскоре находят еще один труп — и снова следователям улыбается каштановый человечек с отпечатками пальцев той же мертвой девочки. -------------------------------------------------- \"Триллер года\". — Джеффри Дивер \"Неистовый триллер в традициях Стига Ларссона\". — А.Дж. Финн \"Соскучились по романам в духе Несбё — прочтите этот\". — The Times \"На этой книге лежит печать успеха\". — Daily Express \"Новый триумф сканди-нуара\". — Metro \"Жутко, закрученно, нашпиговано напряжением\". — Sun \"Высокооктановый триллер\". — The Herald \"Свейструп — выдающийся мастер\". — Telegraph",
