    "publisher": "Издательство АСТ",
    "annotation": "Официальная новеллизация нового фильма. Премьера 1 января 2023 года! Читайте книгу — смотрите фильм! Приучайте детей к чтению!Чебурашка возвращается с удивительными приключениями! Любимый герой поколений и культовый персонаж советского мультфильма — Чебурашка никого не оставляет равнодушным! Вас ждёт душевная история, незабываемые герои и душистый аромат сочных апельсинов. Это лучшая история, чтобы встретить новый год!то, если Чебурашка на самом деле существует?Что, если он — не плюшевая игрушка, а самый настоящий мохнатый зверёк, который живет далеко-далеко на юге, в вечнозелёной апельсиновой роще?Что, если он случайно попадет в городок у моря, встретит одинокого ворчливого старика и изменит сразу несколько жизней?Любимый ушастый герой в новой сказочной истории о дружбе, семье, умении прощать и признавать свои ошибки",
