    "annotation": "Кто бы мог подумать, что бездомный кот Хвост и породистый котёнок Кокосик не только обретут общих хозяев, но станут настоящими друзьями и даже немножко волшебниками - КотоФеями! С помощью летающих шарфа и шапки они совершают добрые дела и маленькие, но очень важные подвиги, выручают друг друга из беды и, конечно, не забывают о приключениях. Если вы ещё не знакомы с КотоФеями, то скорее открывайте эту книгу - ведь в ней собраны все новогодние истории про Хвоста и Кокосика, придуманные и нарисованные чудесной художницей Ольгой Фадеевой. Для дошкольного и младшего школьного возраста",
