    "annotation": "Полистать Первая часть невероятной серии детских детективов от знаменитого автора - Холли Вебб! История о девочке- детективе, которая находи свое первое дело, о котором так давно мечтала! Конечно, никто не предложит Мейзи начать карьеру детектива с поиска похищенных бриллиантов (а хотелось бы!). Первое дело придётся найти самой - например, помочь знакомому мальчику, которого обвинили в краже денег, пропавших из… закрытого на ключ ящика! Здесь мы впервые встречаем Мейзи, девочку, мечтающую стать детективом. А сама Мейзи знакомится со щенком Эдди, который станет её верным помощником! Эта серия книг - приключения для детей и загадка, которую под силу раскрыть ребенку, - под одной обложкой! В книге полно трогательных и смешных моментов и удивительных фактов из истории викторианского Лондона! Полистать",
