    "annotation": "Полистать Мейзи Хитчинс мечтает стать детективом, а пока расследует загадки, которые попадаются на пути. В этой книге она пытается раскрыть секрет маски с красными перьями, а заодно и спасти эту маску от похищения! Серия книг Холли Вебб про девочку-детектива Мейзи Хитчинс уже несколько лет входит в топы продаж. Это образцовый детектив для детей - тайны, которые расследует девочка, под силу разгадать ребёнку! Здесь полно приключений, трогательных и смешных моментов и удивительных фактов из истории викторианского Лондона! Холли Вебб - писательница, популярная во всём мире, но особенно её полюбили в России. Её истории всегда мудрые, поучительные без назидания и очень жизнеутверждающие (а ещё в них всё всегда заканчивается замечательно!). Для среднего школьного возраста. Полистать",
