    "year": "2024",
    "publisher": "",
    "annotation": "Сахарный ребенок (10-е изд.). Книга Ольги Громовой Сахарный ребенок записана ею со слов Стеллы Нудольской, чье детство пришлось на конец 1930-х начало 1940-х годов в Советском Союзе. Это очень личный и берущий за душу рассказ о том, как пятилетняя Эля, счастливо растущая в любящей семье, вдруг оказывается дочерью врага народа и попадает в страшный, непонятный ей мир: после ареста отца их вместе с матерью отправляют в лагерь в Киргизии как ЧСИР (членов семьи изменника Родины) и СОЭ (социально опасные элементы). Но несмотря на все испытания, голод и болезни, которые им приходится пережить, Эля и ее мама не падают духом: читают стихи, поют песни, шутят, по-настоящему заботятся друг о друге. Сахарный ребенок это во многом роман воспитания, история о любви, а еще о том, что такое достоинство и что такое свобода. Точнее всего о свободе говорит мама Эли: Рабство это состояние души. Свободного человека сделать рабом нельзя",
