    "publisher": "Поляндрия No Age",
    "annotation": "Полистать Внезапное появление смертоносного вируса, поражающего животных, стремительно меняет облик мира. Все они — от домашних питомцев до диких зверей — подлежат немедленному уничтожению с целью нераспространения заразы. Употреблять их мясо в пищу категорически запрещено. В этой чрезвычайной ситуации, грозящей массовым голодом, правительства разных стран приходят к радикальному решению: легализовать разведение, размножение, убой и переработку человеческой плоти. Узаконенный каннибализм разделяет общество на две группы: тех, кто ест, и тех, кого съедят. Победитель премии Clarin Novela (2017) Роман «Особое мясо» впервые был опубликован в Аргентине в декабре 2017 года и с тех пор его перевели на 10 языков. Планируется выпуск телесериала на основе книги. Полистать",
