    "annotation": "Как-то раз в Котофеевке завелись мыши. Откуда они взялись - никто не знает. Вот только счастливая жизнь Мурки, жены директора колбасного завода, закончилась: мыши ввалились именно в их дом. Котофеевцы любят рассказывать эту байку, каждый раз добавляя новые подробности… Так что читателю предстоит разобраться, что из этого правда. Но точно с тех пор почтальон Васька гордо носит звание народного любимца, а все соседи решают проблемы исключительно с музыкой! Для дошкольного возраста",
