    "publisher": "ПИТЕР",
    "annotation": "Какого размера капля дождя? Что такое GPS? Откуда берутся вулканы? Почему зимой солнце греет меньше? Когда был изобретен первый компьютер? Почему от прививок больно? Из чего состоят сопли?Всё это реальные вопросы, которые задают дети. Для поиска ответов на такие, кажется, простые вопросы экспертам из разных областей знаний требовались недели: ведь объяснения должны быть понятными и увлекательными, чтобы ребята могли понять, почему мир устроен так, как он устроен. В книге вы найдете ответы на самые популярные вопросы. Благодаря комиксам-схемам даже самая сложная информация становится предельно ясной!Книга стала лауреатом книжной премии науки и образования Франции в категории \"Наука детям\", 2015 (Gout des Sciences 2015). Она была написана редакторами популярного детского научного журнала Images Doc Марком Бейнье и Бертраном Фишу",
