    "annotation": "Накануне Нового года в Котофеевке произошли загадочные события. Сначала гром и молния в зимнем небе. Затем Федя, Вася и Тося устроили погром во дворе тётки Обжорихи. Впрочем, это ещё можно объяснить. Читатели знают, что наша дружная троица любит шалить. А вот снежный гость к праздничному столу — это, пожалуй, станет событием года. Давайте разберёмся во всём по порядку и встретим Новый год с котофеевцами! 5 причин купить книгу: Новогодняя история с трогательным финалом от Рины Зенюк и Игоря Шевчука! Яркие иллюстрации, любимые герои и поучительный сюжет! Идеально подходит для первого самостоятельного чтения. Сказки серии « У нас в Котофеевке» можно читать в любом порядке! Не важно, сколько вам лет, приключения котят никого не оставят равнодушными!",
