    "publisher": "Эксмодетство",
    "annotation": "Полистать История про смелость и умение довериться… щенку! Если щенок будит вас ночью и куда-то зовёт — может, он просит вас кого-нибудь спасти? Книги Холли Вебб всегда мудрые, поучительные без назидания и очень жизнеутверждающие (а ещё в них всё всегда заканчивается замечательно!). Поэтому Холли Вебб популярна во всем мире, но особенно её полюбили в России, где книги писательницы продаются миллионными тиражами. Серия «Добрые зверята» неизменно входит в списки бестселлеров. Множество родителей рассказывают, что их дети просто влюбились в эти истории и начали сами читать. Книга издана на белой бумаге, внутри достаточно крупный шрифт и потрясающей красоты чёрно-белые иллюстрации, которые позволят детям переключать внимание, не нагружая чрезмерно глаза. Полистать",
