    "isbn": "",
    "year": "2022",
    "publisher": "АЙРИС-пресс",
    "annotation": "Книга представляет собой адаптацию сказки знаменитого датского писателя Ханса Кристиана Андерсена (1805-1875) \"Снежная королева\" на английском языке. Это одна из лучших сказок великого писателя, широко известная в нашей стране. В ней рассказывается о том, как детская любовь и искренняя дружба помогла развеять злые чары коварной повелительницы снежного королевства. Данное пособие разработано в соответствии с требованиями действующего Федерального государственного образовательного стандарта (ФГОС). Оно поможет учащимся начальной школы подготовиться к обязательному для каждого ученика итоговому экзамену по английскому языку в новом формате. Сказки адаптированы в учебных целях до уровня Beginner. При этом по возможности сохранено образное и стилевое богатство английского языка. После текста каждой из них следуют комментарий и перевод трудных слов и выражений, а также упражнения, которые учитывают новые требования итоговой аттестации. Они направлены не только на проверку понимания текста, но и на отработку лексики, грамматики, а также развитие умений чтения, аудирования, устной и письменной речи. Упражнения имеют два уровня сложности, что даёт возможность каждому ученику продемонстрировать свой уровень знаний и умений. В конце книги помещён словарь, тест в формате итогового экзамена за 4-й класс, включающий задания по аудированию, а также ответы ко всем упражнениям и тестовым заданиям. Пособие адресовано учащимся 3-4 классов образовательных учреждений, а также широкому кругу лиц, изучающих английский язык",
