    "year": "2019",
    "publisher": "Издательство CLEVER",
    "annotation": "НЕЗАКОННОЕ ПОТРЕБЛЕНИЕ НАРКОТИЧЕСКИХ СРЕДСТВ, ПСИХОТРОПНЫХ ВЕЩЕСТВ, ИХ АНАЛОГОВ ПРИЧИНЯЕТ ВРЕД ЗДОРОВЬЮ, ИХ НЕЗАКОННЫЙ ОБОРОТ ЗАПРЕЩЕН И ВЛЕЧЕТ УСТАНОВЛЕННУЮ ЗАКОНОДАТЕЛЬСТВОМ ОТВЕТСТВЕННОСТЬ. От автора бестселлера \"#ЛюбовьНенависть\" - романтический триллер \"Поклонник\". Впервые Анна Джейн пишет в жанре романтического саспенса! Каждый день Ангелина Ланская получает цветы. Цветов всегда четное количество, и она понятия не имеет, кто их отправитель. Загадочный поклонник намеренно сводит ее с ума, играет, сажает на иглу адреналина и ожидания. Этот человек точно знает, чем ее зацепить. С виду обычная студентка психфака, Ангелина не так безобидна, как кажется. Девушка не помнит свое детство, ее мучает монстр из ночных кошмаров, а порой в ее душе открывается черная бездна. Она - идеальный кандидат для закрытого клуба \"Легион\" на роль жертвы или убийцы? Любовь или смерть? Кровавые ставки уже сделаны! «Поклонник» — романтический триллер с элементами детектива и яркой любовной линией. Он станет замечательным подарком и чудесным дополнением к подарочному комплекту или праздничному набору для тех, кто предпочитает книги редакции Trendbooks и ценит интересную художественную литературу. Бестселлер понравится девушке, любимой женщине, подруге, сестре, маме в качестве сюрприза на день рождения, 8 Марта, 14 февраля (День святого Валентина), Новый год (НГ) и любой другой праздник. Анна Джейн — популярный автор Young Adult бестселлеров для взрослых. Также популярны романы Анны Джейн «ЛюбовьНенависть», «Наследница Черного дракона», «Тайна Черного дракона», «Звезда Черного дракона», «Кошмарных снов, любимая», «Подарок ангела», «Влюбленная ведьма», «Восхитительная ведьма», «Твое сердце будет разбито», «По осколкам твоего сердца», «Запрети любить», которые неоднократно получали призы читательских симпатий LiveLib и насчитывают свыше 22 миллионов прочтений онлайн. Современное издание книги Анны Джейн «Поклонник» предназначено для ценителей эксклюзивной классики, фэнтези и фантастики, философии, триллеров и детективов, исторических романов, энциклопедий человеческой души, бумажной продукции по саморазвитию и психологии",
