    "publisher": "Издательство АСТ",
    "annotation": "Первая книга культовой трилогии о Китнисс Эвердин. Роман провел в списке бестселлеров The New York Times более 100 недель. Литературная основа одноименного фильма с Дженнифер Лоуренс в главной роли. Культовый роман-антиутопия в новом оформлении. Литературная основа одноименного блокбастера с Дженнифер Лоуренс в главной роли. Китнисс Эвердин и Пит Мелларк живут в Дистрикте-12. Они знакомы с детства: когда-то Пит угощал Китнисс хлебом, спасая ее семью от голода, а Китнисс в ответ делилась пойманной на охоте дичью. Теперь же им обоим предстоит принять участие в 74-ых \"Голодных играх\", а победитель на них может быть только один. Если только Китнисс с Питом не заставят организаторов изменить правила. Но сперва нужно как-то пережить два десятка остальных участников. С этой книгой ищут: Коллинз, Сьюзен Коллинз, Голодные игры, Китнисс Эвердин, зарубежная фантастика, антиутопия, Young Adult, Панем, Капитолий, Дистрикт-12",
