    "annotation": "Полистать Лора всегда считала, что счастливцы, у которых есть собаки, должны ответственно подходить к содержанию своих питомцев. Поэтому когда она познакомилась с Генри, милым щенком кинг-чарльз-спаниеля, то очень расстроилась. Хозяйка Генри забывала его кормить и выгуливать, так что Лора поспешила щенку на помощь. Она быстро поладила с Генри и даже более того - полюбила этого милого и деликатного малыша. Но скоро хозяйка Генри уедет и заберет его с собой. Лора в ужасе - с малышом снова будут небрежно обращаться, видя в нем больше мягкую игрушку, нежели живое существо. Как же Лоре спасти малыша? Для среднего школьного возраста. Полистать",
