    "annotation": "\"Подарок ангела и другие рассказы\" — это сборник неизданных историй Анны Джейн, который обязательно понравится поклонникам популярного автора и всем, кто верит в настоящую любовь! В него вошли повести, отрывки и рассказы, созданные писательницей в разные периоды жизни и наполненные теми эмоциями и романтикой, за которые читатели так полюбили бестселлер \"#Любовь Ненависть\", \"Запрети любить\", \"Влюбленная ведьма\" и другие ее романы. В сборнике есть и романтические, и юмористические истории, а вся книга пронизана праздничным настроением благодаря одному из любимейших рассказов читателей \"Подарок ангела\". Книга вышла в двух вариантах обложки с иллюстрациями Карины Яшагиной, а на страницах и перед каждым рассказом ждут атмосферные черно-белые картинки. Сборник станет приятным открытием для подростков и для взрослых поклонников Young Adult, любовных романов Анны Джейни и Trendbooks. Книга в чудесном подарочном оформлении — готовая идея сюрприза для девушек и женщин на Новый год, день рождения, 8 Марта, День святого Валентина и другие праздники. ВАЖНОЕ О КНИГЕ Сборник неизданных историй от автора №1 в России Книга выходит в двух обложках, иллюстрированных Кариной Яшагиной Перед каждым рассказом — атмосферные черно-белые иллюстрации В книге #рассказы #любовь #раннее творчество Возраст 18+",
