    "annotation": "Редьярд Джозеф Киплинг (1865—1936) — английский писатель, журналист и путешественник, лауреат Нобелевской премии по литературе (1907). Именно его перу принадлежит цикл рассказов о мальчике по имени Маугли, воспитанном волками в джунглях Индии. На сегодняшний день эти рассказы являются самыми читаемыми во всем мире, а еще они входят в школьную программу по внеклассному чтению и хрестоматии вместе с не менее известными сказками Редьярда Киплинга («Кошка, гулявшая сама по себе», Рикки-ТиккиТави» и другими).В нашу книгу вошли рассказы о Маугли и сказки «Рикки-Тикки-Тави», «Сноненок», «Кошка, гулявшая сама по себе», «Откуда взялись броненосцы» и другие.Рассказы о Маугли представлены в классическом переводе Н. Дарузес, а сказки в переводе К. Чуковского. Стихи перевел С. Маршак.Для среднего школьного возраста",
