    "annotation": "Приближается Новый год - самый волшебный праздник. Какое желание загадать, что попросить в подарок у Деда Мороза? Маленькой Алисе больше всего на свете нужна мама. Но сможет ли Дед Мороз сотворить такое чудо или мама должна найти Алису сама? А вдруг мама не захочет, чтобы её дочкой была простая девочка? Ведь все мамы мечтают, чтобы их дочки были принцессами. Значит, Алиса сначала должна стать принцессой! А настоящие принцессы обязательно носят платье в горошек... Книга для детей дошкольного и младшего школьного возраста",
