    "annotation": "Немо всегда думал, что получать и распаковывать посылки - это весело. Но с тех пор, как таинственный незнакомец стал отправлять ему коробки с ожившими игрушками (очень опасными!), он понял: не все посылки стоит открывать! Поэтому, когда мальчик получил коробку-сюрприз в третий раз, он вернул её на почту. Но вот незадача - кто-то открыл её вместо него! И над Нудингом воцарилась тьма! Словно кто-то отключил солнце! А это значит, что Немо и его друзьям Фреду и Оде нужно срочно найти того, кто прятался в посылке. Правда, на этот раз им нужно быть очень осторожными! Ведь им придётся иметь дело с чёрной кошкой и кое-кем ещё",
