    "publisher": "Эксмодетство",
    "annotation": "Полистать Айла мечтает о котёнке и с радостью соглашается присмотреть за двумя соседскими котиками. Вдруг родители поймут, какая она ответственная и согласятся завести питомца? Но похоже, что из этой затеи ничего не выйдет. Как только Айла пришла покормить котиков, они сначала чуть не подрались, а потом разбежались. И что Айле делать? Как помочь котикам подружиться? Истории Холли Вебб всегда мудрые, поучительные без назидания и очень жизнеутверждающие (а ещё в них всё всегда заканчивается замечательно!). Поэтому Холли Вебб популярна во всём мире, но особенно её полюбили в России, где книги писательницы продаются миллионными тиражами. Серия \"Добрые зверята\" неизменно входит в списки бестселлеров. Множество родителей рассказывают, что их дети просто влюбились в эти истории и начали сами читать. Книга издана на белой бумаге, внутри достаточно крупный шрифт и потрясающей красоты чёрно-белые иллюстрации, которые позволят детям переключать внимание, не нагружая чрезмерно глаза. Для среднего школьного возраста. Свернуть Полистать",
