    "isbn": "9785000832790",
    "year": "2021",
    "publisher": "",
    "annotation": "Это рассказ о самой обычной семье, с мамой, папой, двумя дочками и бабушкой. Родители ходили на работу, дети - в школу и в сад. А бабушка Женя сидела дома. Она была очень доброй, заботливой и больше всего на свете боялась огорчить сына. Например, чтобы никого не пугать, она не говорила, что вообще-то не сериалы смотрит, а занимается боксом. Однажды папа встретил своего одноклассника, он теперь директор одного чудесного места, где старички и старушки могут отдохнуть от забот. Папа посомневался, но потом все же отправил бабушку Женю в Дом П. О том, что случается, когда мы не говорим друг другу, что чувствуем на самом деле, рассказывает эта повесть. А еще - о том, как важно быть рядом с тем, кого действительно любишь",
