    "publisher": "Эксмодетство",
    "annotation": "Полистать Джеймс нервничал. И не потому, что ему впервые в жизни предстояло ночевать не дома - в конце концов вокруг него будет весь его класс и целых три учительницы. Нет, Джеймс нервничал, потому что боялся темноты и того, что об этом его страхе узнают одноклассники. Тогда все ребята будут смеяться над ним, называть \"малышом\" и уж точно не позовут играть в футбол. Родители не понимали, из-за чего он так переживает. Но только старшая сестра дала хороший совет… Для среднего школьного возраста. Полистать",
