    "annotation": "У пары далматинских догов Понго и Миссис случилось необыкновенное пополнение в семье - пятнадцать прекрасных щенков. Малыши радовали всех, особенно они приглянулись коварной Круэлле де Вил, любительнице мехов и роскошных шубок. Злодейка крадет щенков, а Миссис и Понго без раздумий отправляются в путь, чтобы спасти своих детей. Когда же опасное приключение осталось позади, домой вернулся ни много ни мало сто один далматинец. История, написанная английской писательницей Доди Смит больше полувека назад, вдохновила мультипликаторов студии \"Уолт Дисней\" на создание одного из лучших и практически \"вечных\" мультфильмов. Для детей младшего школьного возраста. / ISBN 978-5-9500430-8-6",
