    "isbn": "9785171557133",
    "year": "2024",
    "publisher": "",
    "annotation": "Захватывающая история о летнем лагере, изобретении ракеты и мутантах в серии \"Камеди Класс!\". Летний лагерь — это безопасность, свежий воздух и добрые вожатые. Так думали родители, собирая Борьку и Ромыча в поездку. Вот пусть и дальше так думают. Им лучше не знать, что их дети прятались от привидения и изобретали ракету, пускали дымовухи и боролись с мутантами. Танцевали и ругались. Любили и дружили. Дрались и ненавидели. И становились чуточку взрослее. \"Камеди Класс!\" — это сборники коротких смешных рассказов для детей и подростков от классных классиков и классных современников. \"Дневник Батарейкина, или Космолагерь зовёт!\" — увлекательная приключенческая книга о летнем лагере, взрослении и. мутантах. А ещё во втором дневнике Борьки Райкина много картинок: его можно читать и как книгу, и как комикс! Это прекрасный подарок для детей и подростков, желающих посмеяться от души и удивиться необыкновенным приключениям. Книга подойдет для внешкольного чтения и чтения с друзьями. Родителям знать не обязательно: ведь всё, что происходит в лагере, остаётся в лагере. Отправляйтесь в фантастические приключения вместе с Борькой и Ромычем!",
