    "year": "2026",
    "publisher": "",
    "annotation": "Дети блокады. Сухачев М.П. Книги о войне детям Серия «Школьная библиотека». Издательство «Детская литература» Повесть Михаила Павловича Сухачёва (1929—2021) рассказывает о блокаде Ленинграда в годы Великой Отечественной войны. С сентября 1941-го по январь 1944 года фашисты каждый день по нескольку раз бомбили и обстреливали город. Более миллиона ленинградцев умерло от голода и холода, но они не сдавались, героически работая и перенося лишения. Герои книги — дети блокадного Ленинграда, Витя Стогов и его друзья, — тушили на чердаках зажигательные бомбы, ловили сигнальщиков-диверсантов, помогали людям выстоять. Любовь к Родине, стойкость, мужество, самоотверженность — вот главные черты этих ребят, благодаря которым они выдержали нечеловеческие испытания. О дальнейшей судьбе ребят, эвакуированных под Томск, в сибирскую деревню, автор рассказал в повести «Там, за чертой блокады» ( 7321023 ). Для среднего школьного возраста",
