    "annotation": "Племя Грустных Медведей отправляется в Тёплые Страны, к Великой Солёной Воде. Их проводником станет Хитрющий Лисёнок - Кроманьонец, великий путешественник и самый лучший на свете Купи-Продай. Неандертальчика и его друзей ждут удивительные каникулы. Отдых на первобытном курорте Солнечные Скалы. Встреча с племенем-близнецом Смеющихся Медведей. Поиск драгоценных Огненных Камней в Гроте Чудес... Каникулы пролетают очень быстро! Захвати купальник или плавки из шкур - и скорее в путь вместе с неандертальским мальчиком и самым весёлым детским художником дядей Колей Воронцовым! Для детей младшего школьного возраста",
