    "publisher": "Издательство Стрекоза",
    "annotation": "Книги для детей дошкольного и младшего школьного возраста. Продолжение сказочных историй \"Нового года не будет!\", \"А Дед Мороз-то ненастоящий!\", \"Где же ты, Снегурочка?\" и \"Следствие ведет Баба Яга\". Перед Новым годом в Вотчине Деда Мороза как всегда предпраздничная суета. Домовой украшает главную елку, Дед Мороз читает письма от ребят и собирает подарки, Баба Яга пишет сценарий праздника. Но тут случилось неожиданно событие: вместе с письмами доставили коробку, на которой было написано: \"Подарок для Бабы Яги\". И что же вы думаете было в посылке? Ключ! И больше ничего. Баба Яга сбилась с ног, пытаясь понять от чего этот ключ и кто его прислал. Ее расследование превратилось в увлекательный квест, к которому подключились все гости. Удастся ли Бабе Яге разгадать тайну ключика? Читайте и узнаете! Художник Елена Теплова",
