    "annotation": "НЕЗАКОННОЕ ПОТРЕБЛЕНИЕ НАРКОТИЧЕСКИХ СРЕДСТВ, ПСИХОТРОПНЫХ ВЕЩЕСТВ, ИХ АНАЛОГОВ ПРИЧИНЯЕТ ВРЕД ЗДОРОВЬЮ, ИХ НЕЗАКОННЫЙ ОБОРОТ ЗАПРЕЩЕН И ВЛЕЧЕТ УСТАНОВЛЕННУЮ ЗАКОНОДАТЕЛЬСТВОМ ОТВЕТСТВЕННОСТЬ. Классика японской литературы в новом переводе. Одно из самых известных произведений Осаму Дадзая. Что остается человеку, если главная цель его жизни — рассмешить всех вокруг? Он готов пойти на любую глупость, лишь бы только не раскрыть своего истинного лица, лица человека глубоко несчастного и одинокого, который заливает свою тоску в баре, развлекается с легкодоступными женщинами и прячет свое истинное \"я\", за сотней разных масок. С этой книгой ищут: Дадзай, Осаму Дадзай, Человек недостойный, японская классика, японская литература, автобиографические книги о писателях",
