    "annotation": "Может ли городской кот - баловень и неженка - оказаться в эпицентре невероятных летних приключений? Ещё как!Коту Егору пришлось покинуть уютную городскую квартиру и оказаться в самом обычном посёлке, где дружно живут пёс Люкс, петух Петя, коза Марта, козел Козел, воробей и другие. Избалованному котику кажется, что лето пройдет скучно и неинтересно... Но жизнь в поселке оказывается настолько захватывающей, полной приключений, тайн и детективных историй, что летние каникулы пролетают незаметно и остается с нетерпением ждать следующего года!В сборник вошли две весёлые, добрые и озорные повести Николая Наволочкина: \"Каникулы кота Егора\" и \"Знакомая корова\", а нарисовала персонажей замечательная художница Ольга Громова",
