    "annotation": "Оказывается, слушать сказки любят не только дети, но и. лошадки! Причём не обыкновенные, а карусельные, из парка аттракционов. За целый день они так устают катать ребятишек, что вечером никак не могут угомониться и заснуть. Поэтому они просят директора парка рассказывать им сказки. Но однажды все-все сказки, которые знал директор, кончились. Осталась одна, самая последняя. Как теперь будут засыпать карусельные лошадки, расскажет знаменитый писатель, автор \"Вредных советов\", циклов сказок \"38 попугаев\" и \"Котёнок по имени Гав\" Григорий Остер",
