    "year": "2024",
    "publisher": "",
    "annotation": "В этой книге читатели вновь встретятся с полюбившимися героями и заглянут в красивый городок у моря, где обитают коты, кошки и мурлики. Там, в старом маяке, живут Кот и мурлик по имени Фирс. Недавно вместе с ними поселилась маленькая Зюря, про которую почти ничего не известно - даже какого она цвета на самом деле. Однажды солнечным утром Зюря увидела, как к берегу причалила лодка. В лодке сидели мурлики, но какие-то странные - в платьях и с музыкальными инструментами, все такие строгие, воспитанные и очень организованные. И, судя по всему, их никто не ждал… Оказалось, это мурлицы! Они приплыли, чтобы дать концерт, вот только все мелодии звучали до того скучно и заунывно! Чтобы спасти положение, Зюря берет дело в свои руки - но не она одна решает вмешаться в ход событий… Чем же закончится этот концерт и что в нем окажется по-настоящему удивительным для наших друзей? Книги о Коте и мурлике полюбились читателям 'Нигмы'. Мы получаем полные добрых слов отзывы и просьбы о продолжении истории. И вот в скором времени новая книга появится на прилавках магазинов. Об авторе: Юрий Бурносов - писатель-фантаст, киносценарист, журналист. Автор более 25 мистических и фантастических романов и рассказов. По первому образованию - фельдшер, затем окончил Брянский университет, факультет русского языка и литературы. Работал журналистом, пресс-секретарем Губернатора Брянской области, редактором ряда региональных изданий и медиа-холдинга. Книги Юрия Бурносова переведены на литовский, эстонский и болгарский языки. Лауреат профессиональных премий, среди которых 'Книга года' - 2007, Медаль Тютчева, премия 'Баст' и другие. Совместно с женой Татьяной Глущенко - автор сценариев телесериалов ('Пятая стража', 'Думай, как женщина', 'Мажор-2', 'Обратная сторона Луны-2'). Об иллюстраторе: Татьяна Глущенко - художник, мультипликатор, сценарист. Окончила Новосибирское художественное училище. Работала в рекламной отрасли. Совместно с мужем, писателем и сценаристом Юрием Бурносовым писала сценарии телесериалов. В 2018 году работала художником-постановщиком на студии 'Союзмультфильм' (анимационный фильм 'Ночная сказка'). Для младшего школьного возраста",
