    "annotation": "К маленькому лисёнку Феньке пришла первая зима. А он и не догадывался, что она может быть такой холодной! К счастью, мама связала Феньке тёплые шапку, шарф и рукавички - а значит, теперь можно и в мороз гулять целыми днями, и лепить снежки сколько хочешь! Вот только это совсем не в радость, когда мама сидит дома - ведь на Фенькину одёжку ушли все шерстяные нитки и для неё самой не осталось. Но Фенька - очень храбрый лисёнок, и, конечно, он отправляется на поиски шерстяных ниток для мамы. Удивительно добрая и нежная сказка Ольги Фадеевой о самом главном не оставит равнодушными маленьких читателей и их родителей, а яркие и обаятельные иллюстрации автора сделают теплее даже самый холодный зимний день",
