    "year": "2025",
    "publisher": "Иностранка",
    "annotation": "Полистать Харри Холе прилетает в Сидней, чтобы помочь в расследовании зверского убийства норвежской подданной. Австралийская полиция не принимает его всерьез, а между тем дело гораздо сложнее, чем может показаться на первый взгляд. Древние легенды аборигенов оживают, дух смерти распростер над землей черные крылья летучей мыши, и Харри, подобно герою, победившему страшного змея Буббура, предстоит вступить в схватку с коварным врагом, чтобы одолеть зло и отомстить за смерть возлюбленной. Это дело станет для Харри началом его несколько эксцентрической полицейской карьеры, а для его создателя, Ю Несбё, - первым шагом навстречу головокружительной мировой славе. НЕЗАКОННОЕ ПОТРЕБЛЕНИЕ НАРКОТИЧЕСКИХ СРЕДСТВ, ПСИХОТРОПНЫХ ВЕЩЕСТВ, ИХ АНАЛОГОВ ПРИЧИНЯЕТ ВРЕД ЗДОРОВЬЮ, ИХ НЕЗАКОННЫЙ ОБОРОТ ЗАПРЕЩЁН И ВЛЕЧЁТ УСТАНОВЛЕННУЮ ЗАКОНОДАТЕЛЬСТВОМ ОТВЕТСТВЕННОСТЬ Полистать",
