    "isbn": "978-5-17-165119-0",
    "year": "2024",
    "publisher": "",
    "annotation": "Мальчишки и девчонки, а также их родители! Криповые истории про школу не хотите ли? \"КАМЕДИ КЛАСС!\" — это сборники коротких смешных рассказов от классных классиков и классных современников. Но на этот раз рассказы будут не только смешными, но и страшно смешными! Как вести себя, если тебя похитили марсиане? Что делать, если учительница превратилась в монстра — а отвечать урок всё равно надо? А может, твой зубной врач оказался настоящим чудовищем? или вдруг выяснилось, что в любимой энциклопедии описаны одни лишь ужасы? как быть, если по соседству завелся призрак?.. Советы по выходу из этих и многих других жутких ситуаций — в новых криповых историях, которые рассказали: Ирина Асеева, Мара Гааг, Вера Гамаюн, Александр Егоров, Анна Зимова, Виктория Медведева, Игорь Родионов, Валерий Роньшин, Елена Шумара и Наталья Щерба. Для любителей бояться по-взрослому мы включили в сборник настоящий ужастик: рассказ Натальи Щербы \"Котам с ключом в зубах не доверяйте\". А для тех, кто любит повеселей, тут есть забавная кринжатина от Валерия Роньшина! Читайте и помните: нервы и чувство юмора лучше всего щекотать одновременно!",
