    "year": "2023",
    "publisher": "Издательство Белая ворона",
    "annotation": "На летние каникулы Артем приезжает в дачный поселок. От всезнающих соседей он узнаёт, что дочь соседей Тоня больна. История, начавшаяся с любопытства и жалости, перерастает в нечто большее. Прогулки на рассвете, разговоры о жизни и смерти, первая влюбленность и пробуждение чувственности… Но вдруг Тоня уезжает, не попрощавшись и не оставив даже номера телефона. В путанице мыслей и чувств Артему приходится принимать непростые решения, договорившись с разумом и сердцем и разгадав загадку Тони. ВКРАТЦЕ: Книга заняла 2-е место на литературном конкурсе «Белой вороны». Нежная книга о первой любви — и ответственности за близких. Автор очень аккуратно затрагивает тему ментальных и телесных недугов, в частности рака. Об авторе. Зуля Стадник родилась в 1984 году в Ульяновске. «Тобольская сказочница» - так окрестил молодую писательницу сайт «Культура РФ». Зуля начала писать после рождения дочери Ассоль, и в ее авторском багаже уже более десятка книг для детей и подростков. ЛИТЕРАТУРНЫЙ КОНКУРС Литературный конкурс «Белой вороны» проводится с 2020 года. Каждый год мы предлагаем авторам, пишущим для детей, новую тему, а затем из нескольких сотен присланных рукописей отбираем лучшие. Мы верим, что литературный конкурс позволит начинающим авторам, чьи произведения отвечают нашим представлениям о детской литературе, найти своего читателя",
