    "annotation": "Полистать Кэсси, младшая сестра Бена - фантазёрка. То она придумывает, будто строители, которые занимаются пристройкой к их дому - отставные пираты, то что к Бену и Кэсси в сад наведывается настоящий медведь. Бен не придавал этому значения, сестрёнка ещё маленькая. Но однажды мальчик узнал, что один из строителей живёт на яхте в компании кота и попугая, будто настоящий пират… Значит, Кэсси не такая уж фантазёрка? Может, и медведь в саду - не выдумка? Для среднего школьного возраста. Полистать",
    "locationNote": "Местоположение: Сагунто. Доступность метро на станциях Colón и Aragón в определённые дни и часы.",
