    "publisher": "Время",
    "annotation": "Не надо было трогать дуб! Тогда бы ничего страшного и не случилось. А когда тронули, тут и началось. Из всех щелей полезла нечисть. Домовые и кабинетные - за наших гимназистов, нечисть - против. Перун мечет молнии на крыше, Кощей (женщина, между прочим) пытается проломить заколдованный круг, говорящий кот подкармливает русалку ворованной колбасой, второй закон Ньютона временно не работает, \"Слово о полку Игореве\" встает перед глазами, словно в формате 3D, а на самом деле наяву - помог волшебный растворитель… Хотите дальше? Сами читайте. 7-е издание",
