    "year": "2021",
    "publisher": "Эксмодетство",
    "annotation": "Лабрадоры - очень умные собаки, в этом девочка Софи убедилась, когда в соседнем доме появился щенок лабрадора по имени Кнопочка. Не было счета ее шалостям и проказам, пытливый ум помогал Кнопочке то устроить подкоп под забором, то выбраться из дома через окно. А когда с хозяином случился несчастный случай, собака сообразила позвать на помощь Софи. Хозяина Кнопочки увезли в больницу, и Софи пришлось упрашивать родителей, чтобы щенок временно пожил у них. Те неохотно согласились, но девочка попала в ловушку, о которой даже не догадывалась. Она и раньше дружила с Кнопочкой, а теперь сильно-сильно к ней привязалась. И что делать Софи, когда хозяина щенка выпишут из больницы? Софи больше не хочет никакой другой собаки, кроме нее… Для среднего школьного возраста",
