    "year": "2023",
    "publisher": "",
    "annotation": "Андрей Жвалевский, Евгения Пастернак. Время всегда хорошее: повесть. 19-е изд. // Что будет, если девчонка из 2018 года вдруг окажется в 1980 году? А мальчик из 1980 года перенесется на ее место? Где лучше? И что такое \"лучше\"? Где интереснее играть: на компьютере или во дворе? Что важнее: свобода и раскованность в чате или умение разговаривать, глядя в глаза друг другу? И самое главное - правда ли, что \"время тогда было другое\"? А может быть, время всегда хорошее и, вообще, всё зависит только от тебя // Книга \"Время всегда хорошее\" - обладатель премии «Алиса» за лучшую фантастическую книгу для детей и юношества, Лауреат Всероссийского конкурса на лучшее литературное произведение для детей и юношества \"Книгуру\", Финалист премии \"Ясная Поляна\" в номинации \"Детство. Отрочество. Юность\", Участник \"длинного списка\" премии \"Baby-НОС\", Победитель читательского конкурса \"Книга года\" Центральной городской детской библиотеки имени Гайдара (Москва), Обладатель почетных знаков \"Нравится детям Ленинградской области\" и \"Нравится детям Белгородской области\" // С 2007 года книга издавалась шестнадцать раз общим тиражом 20000 экземпляров // Что: приключенческая повесть о совершенно реальных школьниках, поменявшихся местами во времени // О чем: не о выдуманной машине времени, а о настоящем советском прошлом и сегодняшнем дне - глазами школьников // На той же полке: лучшая советская подростковая классика - от Булычева и Крапивина до Рыбакова и Лиханова, и одновременно - самые актуальные повести для тинейджеров наших дней // Для кого: Их читают даже самые нечитающие дети! И, добавим, - даже самые «тяжелые на подъем» родители! // Читайте - Андрей Жвалевский, Евгения Пастернак - Время всегда хорошее - Детская фантастика - Подростковая фантастика - Отечественная детская фантастика - Российская детская фантастика - Российская подростковая фантастика - Близкое будущее - Недавнее прошлое - Путешествия во времени - Хроноопера - Попаданцы - Школьники-попаданцы - Советское прошлое - Становление героя - Становление героев - Социальная фантастика - Российская социальная фантастика - Подростковая фантастика - Подростковое фэнтези - Русское подростковое фэнтези - Российское подростковое фэнтези - Отечественное подростковое фэнтези",
