    "isbn": "978-5-04-118376-9",
    "year": "2024",
    "publisher": "Эксмо",
    "annotation": "Фэнтези-новинка от автора бестселлера \"Девочка, которая не видела снов\" Сары Бет Дёрст! \"Искра\" — одиночная книга от любимого тысячами подростков автора. Поступив в школу молний, Мина изо всех сил пытается овладеть навыками грозового стража и обнаруживает, что на самом деле погода в её стране обходится разрушительной ценой, которую влиятельные люди хотят скрыть. Вопреки опасностям на пути Мина и дракон Пиксит решают бросить вызов этому злу. Внутри: лёгкий слог, сильная героиня и её спутник — дракон, необычная атмосфера школы молний и неожиданные повороты сюжета! Красивый макет и запечатанные форзацы! Идеальный подарок для фанатов автора и поклонников вдохновляющего фэнтези. Аналоги — серия \"Скандар\" и книга \"Девочка, которая не видела снов\". Для читателей от 10 лет",
