    "year": "2023",
    "publisher": "Малыш",
    "annotation": "Содержание Однажды в чёрном-чёрном городе произошла страшная-страшная история… На самом-то деле - город был обычным, а история - страшно-смешная, и не одна, а почти 13: про Перчатку-убийцу, Красного Физрука, зомби-мутантов, двух привидений, старый заброшенный дом… ну и про Чёрную руку, конечно! Криповые истории рассказали: Наринэ Абгарян, Анастасия Безлюдная, Мара Гааг, Вера Гамаюн, Наталья Дзе, Александр Егоров, Анна Зимова, Оксана Иванова-Неверова, Елена Пальванова, Любовь {Leo} Паршина и Игорь Родионов. P. S. В этой книге собраны в основном весёлые страшилки, но есть и парочка по-настоящему жутких историй, поэтому предупреждаем: если боитесь, то остановитесь на страницах раздела \"Просто ужас!\". Итак, однажды в чёрном-чёрном городе… Для младшего и среднего школьного возраста. Содержание",
