    "annotation": "Полистать У девочки Беллы сбылась мечта - родители разрешили ей взять собаку. Белла выбрала щенка Сида - беспородного и очень смешного, с огромными пушистыми ушами. Питомец оказался очень понятливым щенком, ласковым, игривым, так что вся семья его полюбила. Но тут Белла поспорила с одноклассницей и запальчиво пообещала вместе с Сидом участвовать в собачьей выставке. Только до выставки совсем мало времени, Белла - начинающий дрессировщик, а надо разучить с Сидом совершенно сногшибательный трюк, чтобы поразить судей и получить первое место. Для младшего школьного возраста. Полистать",
