    "year": "2019",
    "publisher": "Эксмо",
    "annotation": "Петя, Ира и Рудик думали, что их приключения закончились. Но не тут-то было! С помощью таинственных странников Края злой волшебник Нирборих бежит из тюрьмы. Школьники приходят на помощь друзьям-селянам, чтобы разгадать коварные планы волшебника и остановить его. Они не догадываются, что планы странников Края куда страшнее, чем они могут представить. Их ждёт долгий путь, новые друзья, встречи со старыми и новыми врагами, путешествие в Край и даже на дно океана! \"Ира, Петя и Рудик защищают Землю так же смело, как мы с Отшем и Ксандером защищаем Ксенос. В случае чего, я, не раздумывая, обращусь к ним за помощью!\" — Феникс",
