    "publisher": "Акварель",
    "annotation": "Приключения самой непослушной принцессы продолжаются! Нелегкая жизнь у короля - ни минуты покоя! То колдуны нападут, то кран сломается, то придворные решат во что бы то ни стало тебя женить. Но тут - прекрасный повод отложить свадьбу: неизвестные повадились похищать волшебство из Заколдованного Леса. Король Менданбар не мешкая бросается на поиски нахальных воришек. В стране Утренних Гор он встречает принцессу Симорен, у которой и без того характер не сахар, а тут еще любимый дракон исчез непонятно куда. Вот где начинается самое интересное! Для младшего и среднего школьного возраста. / ISBN 978-5-6041499-2-8",
