    "annotation": "Четвертая книга серии о приключениях в Minecraft! \"Майнкрафт\" опасен?! Из-за происков гриферов селяне решили прогнать из \"Майнкрафта\" всех игроков. Ира, Петя, Рудик и Таня отправляются в полное опасностей путешествие, чтобы найти таинственных гриферов. Но лишь пройдя через ущелье Смерти, они узнают, кто ждёт гриферов на опушке. \"Хорошо, что нам с Феникс не встретились такие опасные гриферы. Не уверен, что мы бы с ними справились\". — Ксандер",
