    "audience": "children",
    "cover": "https://imo10.labirint.ru/books/903674/cover.jpg/484-0",
    "isbn": "9785080070242",
    "year": "2023",
    "publisher": "Детская литература",
    "annotation": "ЛОВУШКА ДЛЯ КОТА МОРОЗА Наверняка вы знаете деревню Котофеевку, где живут самые обыкновенные... синие коты ! Красавица Мурка с мужем Степаном, директором колбасного завода, почтальон Василий (кто ещё так сыграет на гармошке!) и даже Валерьяновна с окраины. Однажды под Новый год трое котят решили во что бы то ни стало посмотреть на Кота Мороза - и устроили хитроумную ловушку. А что из этого вышло, вы узнаете, прочитав эту новогодняя история для детей ! Нас находят по запросам: Бестселлеры книги популярные Детская и юношеская книга Детская книга Детские книги сказки Детские сказки для детей 3 лет Для дошкольников Добрые сказкиИздательство Детская литература Книги детские книги Книги для детей 3 года Книги для детей книга Книги для малышей Книги малышам Подарок ребенку Сказка Сказки для детей книги Сказки для малышей книги детские Художественная литература для детей Книги про Новый год Новогодние книги в подарок малышкам Рождество. Книга — волшебный подарок на Новый год и атмосфера праздника для всей семьи! Готовимся к празднику вместе! Мы собрали волшебную подборку, где каждая книга — это готовый подарок на Новый год, билет в сказку и создатель уюта. Ищете идеальный новогодний подарок? Книга в подарок на Новый год — беспроигрышный вариант, который несёт в себе тепло и целый мир историй. Это не просто вещь, а эмоции и новая семейная традиция. Наша праздничная коллекция — это готовые идеи для создания чуда: Для детей: Яркие и добрые приключения, которые создадут неповторимую атмосферу праздника и вызовут настоящий восторг. Это те самые новогодние подарки для детей, которые запомнятся надолго. Для взрослых: Утончённые романы, вдохновляющие истории и красивые издания, которые станут лучшим подарком для близких. Тренды 2026: Мы уже подготовили актуальные подарки на Новый год 2026— бестселлеры и новинки, которые будут в центре внимания. Выбирая новогодний подарок книги, вы дарите настроение и основу для зимних семейных вечеров. Найдите свою идеальную книгу в нашей коллекции и создайте незабываемую магию праздника! Выбрать книгу-подарок и наполнить дом волшебством. Все КНИГИ СЕРИИ «У нас в Котофеевке» (поиск на Wildberries по артикулу): 296028788 - Сборник 1(В сборник вошли пять книг) 608825716 - Сборник 2 (В сборник вошли пять книг) 277580454 - Снежный гость. 217013299 - Сюрприз для мамы. 150462184 - Как Федя Вася и Тося на рыбалку ходили. 171231370 - Большие гонки. 188137047 - Цирк и не только. 135791072 - Ловушка для Кота Мороза. 199632745 - На что ловятся котофеечки. 259765419 - Гуси-Лебеди. 404243525 - Ай да концерт! 208448088 - Кошки-мышки. 233243709 - Книга с наклейками. Круглый год в Котофеевке. 259767560 - Времена года. Раскраска по номерам. 259766772 - Про Федю Васю и Тосю. Раскраска по номерам",
