    "annotation": "Эмили и ее семья живут в волшебном доме. Он словно сошел со страниц сказок - очень старый, полный загадочных вещей, зеркал и потемневших от времени картин. Девочка не раз замечала, что в доме творится странное - то двери цвет поменяют, то пейзаж за окном изменится. Она всегда думала, что ей это просто кажется, но однажды увидела в огромном зеркале в коридоре чужое отражение. А когда Эмили приложила руку к стеклу, то оно подалось, словно пленка. Неужели это дверь в другой мир? Для среднего школьного возраста",
