    "annotation": "Известный цикл повестей К.С. Льюиса о приключениях юных героев в Нарнии! Его книги переводились на 47 языков и экранизировались много раз! Издание включает в себя все 7 повестей и сопровождается великолепными цветными иллюстрациями П. Бейнс, официально признанной \"художницы Нарнии\". Истории о том, как дети из разных поколений одной семьи снова и снова попадают в невероятную сказочную страну. В каждой из повестей героев ждут невероятные приключения в мире, полном мифических существ и говорящих животных. Дети помогают жителям Нарнии бороться со злом и восстанавливать справедливость. Книга станет прекрасным подарком для юных любителей сказочного фэнтези!",
