    "annotation": "Девочка Аля решила написать любимой маме письмо, но буквы никак не хотели её слушаться. Что же случилось? Оказалось, это всё проделки злого Кляксича! Чтобы прогнать хулигана, Аля вместе с храброй буквой А отправляется в волшебное путешествие. По дороге ей предстоит познакомиться со всеми жителями Азбуки – буквами от А до Я. Вместе с Алей обязательно подружатся с буквами и юные читатели этой познавательной и поучительной сказки известной детской писательницы Ирины Токмаковой. Для младшего школьного возраста",
