    "publisher": "Alt Graph",
    "annotation": "События закручиваются стремительным вихрем вокруг Хатимаки: террористы намерены уничтожить всех, кто связан с новой амбициозной экспедицией на Юпитер. Руководство мегакорпорации собирается во что бы то ни стало запустить проект и не считается ни с человеческими жертвами, ни с протестами.В это самое время в жизнь Хатимаки, который оказался зажат между окружающим его насилием, ненавистью и своими амбициями, врываются новые чувства, запутывая всё в конец. Любовь или признание, космос или человечность?! Чтобы разобраться во всём этом, молодому космонавту предстоит спуститься с небес на землю и именно там встретиться лицом к лицу со своими страхами!",
