    "audience": "adult",
    "cover": "https://basket-14.wbbasket.ru/vol2121/part212123/212123792/images/big/1.webp",
    "isbn": "9785699902064",
    "year": "2021",
    "publisher": "Эксмо",
    "annotation": "Пол Каланити с одинаковым успехом мог бы стать как великим врачом, так и великим писателем. В юности он мечтал посвятить свою жизнь английской литературе, но не найдя в ней ответы на свои вопросы о сущности человека, Пол радикально поменял профессию и стал высококлассным нейрохирургом, надеясь лучше познать, что движет людьми и их поступками. Как врач-философ он очень трепетно относился к чувствам своих пациентов и их близких. Ему было всего 36 лет, когда смерть, с которой он боролся каждый день в операционной, постучалась к нему самому. Неутешительный диагноз - рак легких, четвертая стадия - разом перечеркнул все его планы на счастливую семейную жизнь, мечты о научной деятельности и о карьере писателя. Пол мужественно продолжал борьбу с недугом: закончил обучение, спасал пациентов, увидел рождение дочери, размышлял над человеческими возможностями и описал все это в книге, которую вы держите в руках. Эта книга - его завещание дочери, чтобы она знала, каким был ее отец на самом деле; врачам, которые отстраняются от переживаний пациентов; пациентам, которые столкнулись со смертельной болезнью; всем, кто задумывается о смысле жизни и своем предназначении. Пол оставил после себя десятки спасенных жизней, незавершенную рукопись этой книги и маленькую дочку Кэди, которая появилась на свет за 8 месяцев до его смерти. Но Пол остался жить в своей книге, которую с замиранием сердца читают уже в 37 странах и восхищаются силой духа одного-единственного человека, который страстно любил свой язык, обожал свою работу и по-настоящему уважал человека со всеми его чувствами и возможностями",
