    "annotation": "НЕЗАКОННОЕ ПОТРЕБЛЕНИЕ НАРКОТИЧЕСКИХ СРЕДСТВ, ПСИХОТРОПНЫХ ВЕЩЕСТВ, ИХ АНАЛОГОВ ПРИЧИНЯЕТ ВРЕД ЗДОРОВЬЮ, ИХ НЕЗАКОННЫЙ ОБОРОТ ЗАПРЕЩЕН И ВЛЕЧЕТ УСТАНОВЛЕННУЮ ЗАКОНОДАТЕЛЬСТВОМ ОТВЕТСТВЕННОСТЬ. В небольшом городе в Британской Колумбии с особой жестокостью убивают девочку-подростка. Одноклассники утверждают, что ничего не знают, родители молчат. Обвиняемым становится один из учителей, но в деле уйма несостыковок. Проходят годы. Тринити и Джио — создатели подкаста об истории преступлений — берутся за это дело и сталкиваются с тревожными деталями. Им приходится столкнуться с враждебностью целого города и переосмыслить собственные поступки, потому что порой правда гораздо сложнее и страшнее, чем самые жуткие теории",
