    "annotation": "Переезд в другой дом и смена школы посреди учебного года — что может быть хуже? А родители вдруг подарили то, о чем Люси мечтала уже много лет — котёнка. Люси уверена, папа и мама сделали это неспроста — они хотят, чтобы девочка забыла старый дом и старых друзей. Но Люси не хочет забывать. Поэтому она решила притвориться, будто никакой котёнок ей не нужен и не играть с Фиалкой на глазах у семьи. Только девочка не предусмотрела одного — родители, расстроившись оттого, что их подарок не пришелся дочери по сердцу, решат вернуть Фиалку прежней хозяйке. И как поступить Люси, которая уже привязалась к котёнку? Как признаться в своём обмане? Это история о том, как важно вовремя признавать собственные ошибки. Серия-бестселлер! Дети по всему миру обожают эти книги про котят и щенят! Книга издана на белой бумаге, внутри достаточно крупный шрифт и потрясающей красоты чёрно-белые иллюстрации, которые позволят детям переключать внимание, не нагружая чрезмерно глаза. Для младшего школьного возраста. Свернуть",
