    "annotation": "\"Зелёная птица\" — сказочная повесть испанского писателя Хуана Валера-и-Алькала-Гальяно об овдовевшем короле, отважной принцессе и заколдованном злым татарским ханом китайском принце. Теперь историю о преодолении препятствий на пути к любви могут прочитать даже те, кто только начал изучение испанского языка!<br>Текст книги сокращён, адаптирован и сопровождается комментариями и упражнениями с ответами. Также в конце книги вы найдёте небольшой испанско-русский словарь, который поможет вам с выполнением заданий.<br>Пособие предназначается для начинающих изучать испанский язык (уровень 1 — для начинающих А1–А2). Небольшой формат издания позволяет читать произведение как дома, так и в поездке",
