    "year": "2022",
    "publisher": "Эксмодетство",
    "annotation": "Полистать Юная ведьмочка Лотти сдружилась со своим фамилиаром, таксой по имени Софи, и уже с трудом представляет свою жизнь без собаки, любящей кофе, шоколад и поворчать. Кажется, что их дружбе ничего не может помешать… кроме ревности. Лотти решила помочь одному кролику. Его продают в зоомагазине, он сидит в слишком маленькой клетке и выглядит очень грустным. Лотти купила бы его, но у неё не хватает денег, поэтому девочка решила немного поколдовать для зверька. Без Софи с такими чарами не справиться, а такса отказалась что-либо делать. Ей кажется, что Лотти хочет завести себе другого фамилиара, этого самого кролика. И как же Лотти переубедить Софи и объяснить, что она не променяет свою собаку ни на кого в мире, а вот не помочь другому, когда можешь - это попросту неправильно? Для среднего школьного возраста. Полистать",
