    "year": "2022",
    "publisher": "",
    "annotation": "В книгу известной писательницы Любови Федоровны Воронковой (1906 - 1976) входят две повести: «Девочка из города» и «Гуси-лебеди». В первой рассказывается о городской девочке, которая потеряла своих близких во время бомбёжки. Её приютила большая деревенская семья, но как же трудно сироте войти в чужой дом… Однако весной, когда просыпается природа, Валентинка тоже пробуждается для новой жизни… Вторая повесть рассказывает о деревенской девочке, совсем непохожей на других детей. Многие ребята зло посмеиваются над ней, считая некрасивой. Однако за внешним недостатком скрывается внутренняя красота, чистая, отзывчивая душа. Для среднего школьного возраста",
