    "isbn": "9785040919017",
    "year": "2018",
    "publisher": "Эксмодетство",
    "annotation": "Полистать Руби, подруга Лотти, вдруг начала вести себя странно. Вчера ещё они были лучшими подругами и разговаривали цитатами из любимых песен, а сегодня Руби всё время забывает про Лотти и вообще смотрит на неё, будто первый раз видит. Лотти очень встревожилась — похоже, что Руби заколдовали. Ведь недавно в городе объявилась злая колдунья. Сначала она попыталась подчинить себе Лотти, но девочка — ведьма, пусть и начинающая, и смогла справиться с вредоносным заклятием. А Руби — обычный человек, и у неё нет никаких шансов справиться с колдуньей, если Лотти не придёт на помощь. Остались сущие мелочи — найти предмет, при помощи которого колдунья наложила заклятие на Руби. Серия о волшебстве, но волшебстве реальном — о дружбе, о родстве, о чуткости и доброте. А капелька магии ещё никому не повредила! Книгу написала Холли Вебб — автор, популярный во всём мире, но особенно любимый в России. Серию дополняют очаровательнейшие обложки от известного российского художника Алексея Вайнера! Полистать",
    "locationNote": "Местоположение: Сагунто. Доступность метро на станциях Colón и Aragón в определённые дни и часы.",
