    "isbn": "9785906994950",
    "year": "2021",
    "publisher": "Пешком в историю",
    "annotation": "Содержание Карманный путеводитель по городам Золотого кольца для всей семьи. Вместе с мышатами Тимкой и Тинкой мы отправляемся в путешествие по знаменитому маршруту, соединившему старинные русские города вокруг Москвы. Изначально в него входили всего восемь городов: Сергиев Посад, Переславль-Залесский, Ростов Великий, Ярославль, Кострома, Иваново, Суздаль, Владимир. Почти все они сыграли важную роль в становлении Московской Руси: достопримечательности этих городов помогут лучше узнать историю Отечества и погрузиться в атмосферу былых времён. В наш путеводитель включены и другие старинные города неподалёку от основных и славные своими народными промыслами сёла, например Палех, - всего 18 точек маршрута. Для того чтобы посетить все эти места и подробно осмотреть их, понадобится не меньше месяца, но даже если у вас всего один день, вы найдёте в нашем путеводителе основные достопримечательности каждого и сможете организовать путешествие на свой вкус. Для младшего и среднего школьного возраста. Свернуть Содержание",
