    "publisher": "Детская литература",
    "annotation": "В Котофеевке каждый знает: Мурка — хозяйка что надо! Повезло Степану с жёнушкой! Дом у неё всегда сверкает чистотой, пироги вкуснющие, а котята, хоть время от времени и ставят на уши всю деревню, очень воспитанные и заботливые. Кстати говоря, как раз именно накануне маминого праздника Федя, Вася и Тося решили проявить эту самую заботу на полную катушку! Задумали настоящий праздничный сюрприз, да прямо тогда, когда и гости уже на пороге... Интересно узнать у Мурки, как ей сюрприз?!",
