    "isbn": "9785040973521",
    "year": "2018",
    "publisher": "Эксмодетство",
    "annotation": "Полистать Лотти совсем не хотелось выглядеть одинокой отчаявшейся неудачницей, но выбора особо не было. Лотти умудрилась поссорится с самой вредной и злобной девочкой в городе, едва только приехала. А эта злая девочка - признанная заводила в том классе, куда пойдет учиться Лотти, и она пригрозила всем их одноклассницам, что будет издеваться над любой, кто попробует даже заговорить с новенькой. Но только одна девочка, Руби, не послушалась вредину. Руби оказалась весёлой и умной, и Лотти очень захотелось с ней подружиться. Но есть одна проблема. Лотти, помимо всех неприятностей в новой школе, ещё и начинающая ведьма. И рано или поздно Руби сведет всё странности воедино - она же не глупая. И Лотти думает: признаться сейчас или подождать, когда Руби сама догадается? И захочет ли вообще она дружить с ведьмой? Полистать",
