    "year": "2020",
    "publisher": "Эксмодетство",
    "annotation": "Полистать Девочка Люси мечтала о котёнке. Так мечтала, что соврала однокласснице в новой школе, будто бы у нее есть питомец. На самом деле это была не совсем ложь — Люси в саду нашла крохотную голодную кошечку, назвала ее Кэтти и устроила ей уютный дом в шкафу в своей комнате. Только вот ни папа, ни бабушка не знают, что у Люси завелся питомец. Вдобавок папа всегда говорил, что бабушка против животных в доме. И как теперь Люси признаться в своем секрете? Ведь папа и бабушка могут потребовать, чтобы девочка отдала Кэтти в приют. А еще надо объясниться с одноклассницей… Это история про ошибки и преувеличения. И как же главной героине из них выпутаться? Холли Вебб — писательница, популярная во всём мире, но особенно её полюбили в России, что подтверждают многомиллионные тиражи. Книга издана на белой бумаге, внутри крупный шрифт и красивые чёрно-белые иллюстрации, которые позволят детям переключать внимание, не нагружая глаза. Идеальна для родителей, которые хотят, чтобы дети втянулись в чтение. Для младшего школьного возраста. Свернуть Полистать",
    "locationNote": "Местоположение: Сагунто. Доступность метро на станциях Colón и Aragón в определённые дни и часы.",
    "sourceUrl": "https://www.labirint.ru/books/535079/",
