    "year": "2023",
    "publisher": "",
    "annotation": "Один из самых популярных авторов современного молодёжного романа. Более 1 000 000 поклонников на просторах Рунета! Её книги — это истории о любви, романтике, о дружбе и доброте, приправленные неиссякаемым юмором. Ее герои всегда интересные личности, с которыми просто невозможно скучать и невозможно расстаться. Диана – певица, покорившая своим голосом миллионы людей. Она красива, талантлива и популярна. В нее влюблены Дастин - известный актер, за красивым лицом которого скрывается надменность и холодность, и Кристиан - незаконорожденный сын богатого человека, привыкший получать все, что хочет. Но никто не знает, что голос Дианы - это Санни, талантливая студентка музыкальной школы искусств. И пока на сцене одна, за сценой поет другая. Что заставило Санни продать свой голос? Сколько стоит чужой талант? Кто будет достоин любви, а кто останется ни с чем? И что победит: истинный талант или деньги? Небесная музыка начинает играть над их головами",
